window.NHZ_YUWEN = {"grammar":{"categories":[{"id":"cilei","items":[{"name":"名词","例子":["老师、北京（人物/处所）","春天、昨天（时间）","上面、中间（方位）","我的书包、小明的生日","三本书、两个人（名词前能加数量词）","花开了、春天来了（名词能作主语）"],"口诀":"人事物时地，名词要牢记","易错":"方位词常被误认为副词","讲解":"表示人、事物、时间、处所、方位等的词","深讲":"名词是给人、事物、时间、处所、方位起的名字。分五小类：人物（老师、妈妈）、事物（书包、苹果）、时间（春天、昨天）、处所（北京、学校）、方位（上面、中间）。名词一般能做主语和宾语，前面常能加数量词，如“三本书”“两个人”。","怎么认":["前面能不能加数量词？能加“三本、两个”的，多半是名词。","能不能回答“谁/什么”？能回答“谁来了、什么掉了”的，多半是名词。","前面能不能加“很”？名词一般不能说“很书包、很北京”。"],"辨析":"名词和代词都指人或事物，但代词是“替身”：他、这、那不指具体名字，换了场合指的东西就变了；名词是固定名字，换场合还是它。方位词是名词里的一小类，只表示方向和位置。","例句解析":[{"句":"小明在北京看书。","析":"“北京”是处所名词，说明看书的地方；“书”是事物名词，是“看”的对象。"},{"句":"春天来了，花开了。","析":"“春天”是时间名词，作主语，说明什么时候；“花”是事物名词。"}],"练习":[{"q":"下面哪个词是名词？","options":["跑步","桌子","很快","在"],"answer":1,"解析":"“桌子”是事物名词；“跑步”是动词，“很快”是副词加形容词，“在”是介词。"},{"q":"“昨天”是什么词？","options":["动词","时间名词","副词","形容词"],"answer":1,"解析":"“昨天”表示时间，是时间名词。"},{"q":"“书在上面”中，“上面”是？","options":["副词","方位名词","动词","连词"],"answer":1,"解析":"“上面”是方位词，属于名词，不要因为它在句末就当成副词。"}],"图示":"<svg viewBox=\"0 0 256 110\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><path d=\"M7,3 13,22 1,22\" fill=\"#7b1fa2\" transform=\"translate(17,5)\"/><text x=\"32\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">他</text><text x=\"32\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">代词</text><path d=\"M15,15 m-9,0 a9,9 0 1,0 18,0 a9,9 0 1,0 -18,0\" fill=\"#d32f2f\" transform=\"translate(81,5)\"/><text x=\"96\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">是</text><text x=\"96\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">动词</text><path d=\"M5,5 h20 v20 h-20 z\" fill=\"#00897b\" transform=\"translate(145,5)\"/><text x=\"160\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">一名</text><text x=\"160\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">数词</text><path d=\"M7,3 13,22 1,22\" fill=\"#222\" transform=\"translate(209,5)\"/><text x=\"224\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">教师</text><text x=\"224\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">名词</text><text x=\"128\" y=\"108\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">每个实词头上戴着自己的符号帽——看形状颜色就知道身份</text></svg>","类比":"名词的符号是一座<b>黑色小山</b>▲，稳稳地立在那里——就像万物的名字，稳定、实在。你能摸到、看到、想到的东西，都有名字：桌子、北京、勇气、昨天。","subtitle":"万物的名字「黑三角」"},{"name":"动词","例子":["跑、吃（动作）","喜欢、害怕（心理）","有、在（存在）","我每天跑步上学","会游泳、能跑步（能愿动词）","跑着、吃了、去过（动词后能加着、了、过）"],"口诀":"动作心理变化，动词来表达","易错":"“是”有时是动词（判断），有时是副词（强调）","讲解":"表示动作、行为、心理活动、存在变化的词","深讲":"动词表示动作、行为、心理活动和存在变化。分动作（跑、吃）、心理（喜欢、害怕）、存在（有、在）、能愿（会、能、要）、趋向（来、去、上、下）。动词一般能作谓语，常常能带宾语，动作动词后面常能加“着、了、过”。","怎么认":["能不能带宾语？“吃什么、看什么”能接上宾语的，多半是动词。","后面能不能加“着、了、过”？“跑着、吃了、去过”都通顺的，多半是动词。","前面能不能加“很”？动作动词一般不能说“很跑、很吃”（喜欢这类心理动词是例外）。"],"辨析":"动词和形容词都常作谓语，但动词讲“做什么”，形容词讲“怎么样”；“他跑得快”里“跑”是动词，“快”是形容词，讲跑的样子。动词和副词也别混：副词是修饰动词的“小跟班”，自己不当谓语中心。","例句解析":[{"句":"小狗在草地上跑。","析":"“跑”是动作动词，作谓语；“在草地上”是地点，说明跑的地方。"},{"句":"我喜欢踢足球。","析":"“喜欢”是心理动词，作谓语；“踢足球”是它带的宾语，说明喜欢什么。"}],"练习":[{"q":"下面哪个词是动词？","options":["美丽","跳绳","很","的"],"answer":1,"解析":"“跳绳”是动作动词；“美丽”是形容词，“很”是副词，“的”是助词。"},{"q":"“害怕”属于哪类动词？","options":["动作动词","心理动词","形容词","副词"],"answer":1,"解析":"“害怕”表示心理活动，是心理动词。"},{"q":"“他跑得很快”中，“跑”是？","options":["形容词","副词","动词","名词"],"answer":2,"解析":"“跑”讲做什么，是动词；“快”讲跑的样子，是形容词。"}],"图示":"<svg viewBox=\"0 0 320 110\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><path d=\"M7,3 13,22 1,22\" fill=\"#222\" transform=\"translate(17,5)\"/><text x=\"32\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">小狗</text><text x=\"32\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">名词</text><path d=\"M15,3 A9,9 0 1,0 15,21\" fill=\"#2e7d32\" transform=\"translate(81,5)\"/><text x=\"96\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">在</text><text x=\"96\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">介词</text><path d=\"M15,15 m-5,0 a5,5 0 1,0 10,0 a5,5 0 1,0 -10,0\" fill=\"#ef6c00\" transform=\"translate(145,5)\"/><text x=\"160\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">飞快</text><text x=\"160\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">副词</text><path d=\"M15,15 m-4,0 a4,4 0 1,0 8,0\" fill=\"#78909c\" transform=\"translate(209,5)\"/><text x=\"224\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">地</text><text x=\"224\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">助词</text><path d=\"M15,15 m-9,0 a9,9 0 1,0 18,0 a9,9 0 1,0 -18,0\" fill=\"#d32f2f\" transform=\"translate(273,5)\"/><text x=\"288\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">跑</text><text x=\"288\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">动词</text><text x=\"160\" y=\"108\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">每个实词头上戴着自己的符号帽——看形状颜色就知道身份</text></svg>","类比":"动词的符号是一颗<b>大红太阳</b>●，散发能量——句子没有动词就像汽车没有发动机，跑不起来。跑、吃、喜欢、是，都是动作或状态。","subtitle":"动作的发动机「大红圆」"},{"name":"形容词","例子":["红、方（形状）","善良、勇敢（性质）","迅速、雪白（状态）","今天的太阳暖洋洋的","很红、非常勇敢（形容词前能加很）","花很红（形容词能作谓语）"],"口诀":"形状性质状态，形容词来扮","易错":"副词“很”+形容词是常见搭配，别把“很”当形容词","讲解":"表示人或事物的形状、性质、状态的词","深讲":"形容词表示人或事物的形状、性质和状态。分性质（善良、勇敢）、形状（方、圆）、状态（雪白、暖洋洋）。形容词一般能受“很、非常”修饰，不能带宾语；作定语时常带“的”，作谓语时直接说明主语怎么样，作补语时说明动作的结果或样子。","怎么认":["前面能不能加“很”？“很红、很勇敢”通顺的，多半是形容词。","后面能不能带宾语？形容词一般不能说“红书、快饭”这样的搭配。","能不能回答“怎么样”？能回答主语“怎么样”的，多半是形容词。"],"辨析":"形容词和副词都和程度有关，但形容词能作谓语（“花很红”），副词不能单独作谓语，只能修饰别人。“很”本身是副词，不是形容词。状态形容词如“雪白、暖洋洋”一般不受“很”修饰，不能说“很雪白”。","例句解析":[{"句":"今天的太阳暖洋洋的。","析":"“暖洋洋”是状态形容词，作谓语，说明太阳的样子。"},{"句":"雪白的墙真干净。","析":"“雪白”是形容词，作定语，修饰“墙”；“干净”也是形容词，作谓语。"}],"练习":[{"q":"下面哪个词是形容词？","options":["跑","美丽","在","把"],"answer":1,"解析":"“美丽”表示性质，是形容词；“跑”是动词，“在”是介词，“把”是介词。"},{"q":"“雪白的墙”中，“雪白”是？","options":["名词","动词","形容词","副词"],"answer":2,"解析":"“雪白”表示墙的样子，作定语，是形容词。"},{"q":"“很”是什么词？","options":["形容词","副词","动词","名词"],"answer":1,"解析":"“很”修饰形容词和动词，自己是副词，别把跟班当主角。"}],"图示":"<svg viewBox=\"0 0 320 110\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><path d=\"M7,3 13,22 1,22\" fill=\"#1565c0\" transform=\"translate(17,5)\"/><text x=\"32\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">美丽</text><text x=\"32\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">形容词</text><path d=\"M15,15 m-4,0 a4,4 0 1,0 8,0\" fill=\"#78909c\" transform=\"translate(81,5)\"/><text x=\"96\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">的</text><text x=\"96\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">助词</text><path d=\"M7,3 13,22 1,22\" fill=\"#222\" transform=\"translate(145,5)\"/><text x=\"160\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">花</text><text x=\"160\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">名词</text><path d=\"M15,15 m-9,0 a9,9 0 1,0 18,0 a9,9 0 1,0 -18,0\" fill=\"#d32f2f\" transform=\"translate(209,5)\"/><text x=\"224\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">开</text><text x=\"224\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">动词</text><path d=\"M15,15 m-4,0 a4,4 0 1,0 8,0\" fill=\"#78909c\" transform=\"translate(273,5)\"/><text x=\"288\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">了</text><text x=\"288\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">助词</text><text x=\"160\" y=\"108\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">每个实词头上戴着自己的符号帽——看形状颜色就知道身份</text></svg>","subtitle":"名词的化妆师「蓝三角」","类比":"形容词的符号是一座<b>蓝色小山</b>▲，紧挨着名词的黑三角——它是名词的化妆师，专门描述样子：红的花、善良的人、雪白的墙。"},{"name":"数词","例子":["一、两、百","第一、初三","我们班有45个同学","一、二、三（基数）","第一、第二（序数）","几、许多（概数）","三个苹果、第一名","两个人、两本书（量词前用两）","二月、第二名（读数和序数用二）"],"口诀":"数目次序，数词管住","易错":"“两”和“二”用法不同：序数用“二”，量词前多用“两”","讲解":"表示数目和次序的词","深讲":"数词表示数目和次序。分基数（一、二、三……）、序数（第一、第二……）和概数（几、许多、大约）。数词常常和量词一起用，组成数量短语，如“三个苹果”“第一名”。数词本身不指具体东西，要和量词、名词搭在一起才完整。","怎么认":["是不是表示“几个、第几个”？是的，多半是数词。","后面能不能跟量词？“三只、五本、第一”后面常跟量词或名词。","“二”和“两”要分场合：读数、序数用“二”（二月、第二），量词前面多用“两”（两个人、两本书）。"],"辨析":"数词和量词是一对搭档：数词管“多少”，量词管“用什么单位量”。“三”单独不能说“三书”，要说“三本书”；“只”单独也不能表数，要说“三只”。","例句解析":[{"句":"教室里有三只小猫。","析":"“三”是数词，“只”是量词，“三只”合起来修饰“小猫”，说明数量。"},{"句":"他在比赛中得了第一名。","析":"“第一”是序数词，表示次序，不是数量；“名”是量词。"}],"练习":[{"q":"下面哪个词是数词？","options":["只","三","本","个"],"answer":1,"解析":"“三”表示数目，是数词；“只、本、个”都是量词。"},{"q":"“两个人”中，为什么不用“二”？","options":["量词前多用“两”","读数用“两”","序数用“两”","都可以"],"answer":0,"解析":"量词前面多用“两”，如两个人、两本书；读数和序数才用“二”。"},{"q":"“第二名”中，“第二”是？","options":["基数","序数","量词","概数"],"answer":1,"解析":"“第二”表示次序，是序数词。"}],"图示":"<svg viewBox=\"0 0 30 30\" width=\"44\" height=\"44\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"5\" y=\"5\" width=\"20\" height=\"20\" rx=\"4\" fill=\"#00897b\"/></svg><div style=\"font-size:12px;color:#888;text-align:center\">蒙特梭利符号：青方</div>"},{"name":"量词","例子":["个、只、条","米、公斤、次","一本书、三只小猫","个、只、条、本（名量词）","次、遍、回（动量词）","三个苹果、这本书","看三遍、跑两趟","一条鱼、一座山","一本鱼（错：量词搭配不对）"],"口诀":"名量（个只条）+动量（次回遍）","易错":"量词重叠表“每一”，如“个个”","讲解":"表示计量单位的词","深讲":"量词表示计量单位，分名量词和动量词。名量词量人或事物（个、只、条、本、张、座），动量词量动作的次数（次、遍、回、趟）。量词前面常有数词或指示代词（这、那），后面跟名词或动词，如“这本书”“看三遍”。","怎么认":["是不是跟在数词或“这、那”后面量东西？“三个、这本”里的“个、本”就是量词。","量的是人或物，还是动作次数？量人或物的是名量词，量次数的是动量词。","换一个量词试试：说“一条鱼”通顺，“一本鱼”就不通顺，量词和名词要搭配。"],"辨析":"量词和名词别混：名词是东西的名字，量词是量的单位。“书”是名词，“本”是量词。量词也不能单独表数，“本”不说“有几本”，要说“有几本书”。","例句解析":[{"句":"桌上有一条鱼。","析":"“条”是名量词，和鱼搭配；换成“本”就不通顺，说明量词要和名词配对。"},{"句":"这篇课文我读了三遍。","析":"“遍”是动量词，量动作“读”的次数，不是量课文本身。"}],"练习":[{"q":"“一座桥”中，量词是？","options":["一","座","桥","的"],"answer":1,"解析":"“座”是量词，量桥；“一”是数词，“桥”是名词。"},{"q":"下面哪个是动量词？","options":["只","本","遍","条"],"answer":2,"解析":"“遍”量动作的次数，是动量词；其余都是名量词。"},{"q":"下面哪组搭配不对？","options":["一条鱼","一本书","一座山","一本鱼"],"answer":3,"解析":"鱼用“条”不用“本”，量词要和名词搭配。"}],"图示":"<svg viewBox=\"0 0 30 30\" width=\"44\" height=\"44\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"8\" y=\"5\" width=\"14\" height=\"20\" rx=\"7\" fill=\"#00897b\" opacity=\"0.6\"/></svg><div style=\"font-size:12px;color:#888;text-align:center\">蒙特梭利符号：青椭圆</div>"},{"name":"代词","例子":["我、你、他（人称）","这、那（指示）","谁、怎么（疑问）","这是我的铅笔，那是你的","这、那、这里（指示）","谁、什么、哪里（疑问）","小明来了，他也来了","这是什么、那是谁","我们、你们、他们"],"口诀":"人称指示疑问，代词三剑客","易错":"“这”“那”+量词+名词是代词性用法","讲解":"代替名词、动词、形容词等的词","深讲":"代词是代替名词、动词、形容词等实词的词，分人称（我、你、他、我们）、指示（这、那、这里、那里）、疑问（谁、什么、哪里、怎么）。代词的好处是不用重复名字：说过“小明”后，后面用“他”代替，句子就简洁了。","怎么认":["是不是在代替前面出现过的人或事物？是的，多半是代词。","换一个具体名字试试：把“他”换成“小明”，句子意思不变，说明“他”是代词。","是不是在提问？“谁、什么、哪里”提问的，多半是疑问代词。"],"辨析":"代词和名词都能指人指物，但名词是固定名字，代词是“替身”，离开上下文就不知道指谁。“他”在不同句子里可以是小明，也可以是小刚；“小明”永远是小明。","例句解析":[{"句":"小明来了，他手里拿着一本书。","析":"第二个分句的“他”代替前面的“小明”，避免重复。"},{"句":"这是什么？","析":"“这”是指示代词，指眼前这个东西；“什么”是疑问代词，用来提问。"}],"练习":[{"q":"下面哪个词是代词？","options":["桌子","他们","跑步","美丽"],"answer":1,"解析":"“他们”是人称代词；“桌子”是名词，“跑步”是动词，“美丽”是形容词。"},{"q":"“谁来了？”中，“谁”是？","options":["名词","疑问代词","动词","副词"],"answer":1,"解析":"“谁”用来提问，是疑问代词。"},{"q":"“他”在不同句子里指的人一样吗？","options":["一样","不一定，要看上下文","永远是小明","不能指人"],"answer":1,"解析":"代词是替身，指谁要看上下文，不能只看词本身。"}],"图示":"<svg viewBox=\"0 0 320 110\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><path d=\"M7,3 13,22 1,22\" fill=\"#7b1fa2\" transform=\"translate(17,5)\"/><text x=\"32\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">这</text><text x=\"32\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">代词</text><path d=\"M15,15 m-9,0 a9,9 0 1,0 18,0 a9,9 0 1,0 -18,0\" fill=\"#d32f2f\" transform=\"translate(81,5)\"/><text x=\"96\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">是</text><text x=\"96\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">动词</text><path d=\"M7,3 13,22 1,22\" fill=\"#7b1fa2\" transform=\"translate(145,5)\"/><text x=\"160\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">我</text><text x=\"160\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">代词</text><path d=\"M15,15 m-4,0 a4,4 0 1,0 8,0\" fill=\"#78909c\" transform=\"translate(209,5)\"/><text x=\"224\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">的</text><text x=\"224\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">助词</text><path d=\"M7,3 13,22 1,22\" fill=\"#222\" transform=\"translate(273,5)\"/><text x=\"288\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">书</text><text x=\"288\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">名词</text><text x=\"160\" y=\"108\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">每个实词头上戴着自己的符号帽——看形状颜色就知道身份</text></svg>","subtitle":"名词的替身「紫三角」","类比":"代词的符号是一座<b>紫色小山</b>▲，和名词的黑三角是亲戚——它是名词的替身演员：我、你、他、这、那、谁，不用每次都喊全名。"},{"name":"副词","例子":["很、非常（程度）","都、只（范围）","已经、正在（时间）","他跑得非常快","常常、总是（频率）","不、没（否定）","也许、大概（语气）"],"口诀":"程度范围时间，副词来限制","易错":"副词一般不能单独做谓语","讲解":"修饰动词、形容词，表示程度、范围、时间等的词","深讲":"副词修饰动词、形容词，表示程度、范围、时间、频率、语气、否定等。分程度（很、非常）、范围（都、只）、时间（已经、正在）、频率（常常、总是）、否定（不、没）、语气（也许、大概）。副词一般放在谓语前面，不能修饰名词，前面一般不能再加“很”。","怎么认":["是不是站在动词或形容词前面修饰它？“已经来了、非常快”里的“已经、非常”就是副词。","能不能修饰名词？副词一般不能说“很书包、都桌子”。","删掉它试试：删掉副词，句子主干还在，只是程度、时间、范围的意思弱了。"],"辨析":"副词和形容词都和程度有关，但形容词能作谓语（“花很红”），副词不能单独作谓语，只能修饰别人。“很”本身是副词，不是形容词。","例句解析":[{"句":"他已经写完了作业。","析":"“已经”是时间副词，放在动词“写”前面，说明动作完成了。"},{"句":"同学们都来了。","析":"“都”是范围副词，说明“同学们”一个不落，全都来了。"}],"练习":[{"q":"下面哪个词是副词？","options":["桌子","已经","跑步","美丽"],"answer":1,"解析":"“已经”表示时间，是副词；“桌子”是名词，“跑步”是动词，“美丽”是形容词。"},{"q":"“非常快”中，“非常”是？","options":["形容词","副词","动词","名词"],"answer":1,"解析":"“非常”修饰形容词“快”，自己是副词。"},{"q":"副词一般不能修饰？","options":["动词","形容词","名词","谓语"],"answer":2,"解析":"副词修饰动词和形容词，一般不能修饰名词。"}],"图示":"<svg viewBox=\"0 0 448 110\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><path d=\"M7,3 13,22 1,22\" fill=\"#7b1fa2\" transform=\"translate(17,5)\"/><text x=\"32\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">他</text><text x=\"32\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">代词</text><path d=\"M15,15 m-5,0 a5,5 0 1,0 10,0 a5,5 0 1,0 -10,0\" fill=\"#ef6c00\" transform=\"translate(81,5)\"/><text x=\"96\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">已经</text><text x=\"96\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">副词</text><path d=\"M15,15 m-5,0 a5,5 0 1,0 10,0 a5,5 0 1,0 -10,0\" fill=\"#ef6c00\" transform=\"translate(145,5)\"/><text x=\"160\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">飞快</text><text x=\"160\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">副词</text><path d=\"M15,15 m-4,0 a4,4 0 1,0 8,0\" fill=\"#78909c\" transform=\"translate(209,5)\"/><text x=\"224\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">地</text><text x=\"224\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">助词</text><path d=\"M15,15 m-9,0 a9,9 0 1,0 18,0 a9,9 0 1,0 -18,0\" fill=\"#d32f2f\" transform=\"translate(273,5)\"/><text x=\"288\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">跑</text><text x=\"288\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">动词</text><path d=\"M15,15 m-9,0 a9,9 0 1,0 18,0 a9,9 0 1,0 -18,0\" fill=\"#d32f2f\" transform=\"translate(337,5)\"/><text x=\"352\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">出</text><text x=\"352\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">动词</text><path d=\"M7,3 13,22 1,22\" fill=\"#222\" transform=\"translate(401,5)\"/><text x=\"416\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">教室</text><text x=\"416\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">名词</text><text x=\"224\" y=\"108\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">每个实词头上戴着自己的符号帽——看形状颜色就知道身份</text></svg>","subtitle":"动词的小跟班「小橙圆」","类比":"副词的符号是一颗<b>小橙圆</b>，紧挨着动词的大红圆——小圆是大圆的跟班，专门给动作加说明：怎么跑（飞快地跑）、多深（很爱）、什么时候（已经走了）。"},{"name":"介词","例子":["在、从、向（方向）","把、被（对象）","关于、对于","我在教室里写作业","在教室、从北京（处所）","给妈妈、对他（对象）","向老师请教（方向）","为班级争光（目的）","比他高（比较）","把书放在桌上（处置）"],"口诀":"在从把被关于，介词引对象","易错":"“把”字句和“被”字句是中考重点句式","讲解":"用在名词、代词前，组成介词短语，表示方向、对象等的词","深讲":"介词引出时间、处所、对象、方式、原因等，和后面的名词、代词组成介宾短语。常见介词有在、从、向、往、给、对、为、比、跟、把、被。介宾短语常常作状语（“在教室里读书”）、补语（“来自北京”）或定语（“对他的关心”），但介词自己不能单独作谓语中心。","怎么认":["后面是不是跟了一个名词或代词？“在教室、给妈妈、对他”这种结构，多半是介词短语。","能不能单独作谓语？介词自己不能单独作谓语中心，要和后面的词组成短语。","换成动词试试还通不通？介词后面的词不能像动词那样带“着、了、过”。"],"辨析":"介词和连词最容易混，关键看换位：连词“和”连接的“苹果和香蕉”可以换成“香蕉和苹果”，意思不变；介词引出的部分换位置就变味或不通，如“他向老师请教”换成“老师向他请教”，主角就换了人。","例句解析":[{"句":"小明在教室里看书。","析":"“在教室里”是介宾短语，作状语，说明看书的地点；“在”是介词。"},{"句":"妈妈给弟弟讲故事。","析":"“给弟弟”是介宾短语，说明讲故事的对象；这里的“给”引出对象，是介词。"}],"练习":[{"q":"“在教室里”中，“在”是？","options":["动词","介词","副词","连词"],"answer":1,"解析":"“在”引出地点，和“教室里”组成介宾短语，是介词。"},{"q":"下面哪个是介词短语？","options":["跑得快","在学校","很美丽","三本书"],"answer":1,"解析":"“在学校”是介词加名词组成的介宾短语；其余不是。"},{"q":"介词一般不能？","options":["跟名词","作状语","单独作谓语中心","组成短语"],"answer":2,"解析":"介词要和后面的词组成短语，不能单独作谓语中心。"}],"图示":"<svg viewBox=\"0 0 384 110\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><path d=\"M7,3 13,22 1,22\" fill=\"#7b1fa2\" transform=\"translate(17,5)\"/><text x=\"32\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">我</text><text x=\"32\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">代词</text><path d=\"M15,3 A9,9 0 1,0 15,21\" fill=\"#2e7d32\" transform=\"translate(81,5)\"/><text x=\"96\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">从</text><text x=\"96\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">介词</text><path d=\"M7,3 13,22 1,22\" fill=\"#222\" transform=\"translate(145,5)\"/><text x=\"160\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">北京</text><text x=\"160\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">名词</text><path d=\"M15,3 A9,9 0 1,0 15,21\" fill=\"#2e7d32\" transform=\"translate(209,5)\"/><text x=\"224\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">到</text><text x=\"224\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">介词</text><path d=\"M7,3 13,22 1,22\" fill=\"#222\" transform=\"translate(273,5)\"/><text x=\"288\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">上海</text><text x=\"288\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">名词</text><path d=\"M15,15 m-9,0 a9,9 0 1,0 18,0 a9,9 0 1,0 -18,0\" fill=\"#d32f2f\" transform=\"translate(337,5)\"/><text x=\"352\" y=\"65\" font-size=\"18\" text-anchor=\"middle\">去</text><text x=\"352\" y=\"88\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">动词</text><text x=\"192\" y=\"108\" font-size=\"11\" fill=\"#888\" text-anchor=\"middle\">每个实词头上戴着自己的符号帽——看形状颜色就知道身份</text></svg>","subtitle":"方位的月亮「绿新月」","类比":"介词的符号是一弯<b>绿色新月</b>☽，总在名词前面带路：在哪里（在公园）、从哪里（从北京）、向哪里（向南）。它像路标，指引方向。"},{"name":"连词","例子":["和、跟（并列）","但是、然而（转折）","因为、所以（因果）","我喜欢画画，也喜欢唱歌","苹果和香蕉（并列）","虽然累，但是坚持（转折）","因为下雨，所以取消（因果）","如果下雨，就回家（假设）","不是苹果，而是香蕉（选择）","老师和同学（可换位）"],"口诀":"连接上下，关系靠它","易错":"关联词搭配要完整，如“不仅……而且”不能丢一半","讲解":"连接词、短语、句子，表示并列、转折等关系的词","深讲":"连词连接词、短语或分句，表示并列、转折、因果、假设、选择等关系。常见连词有和、及、或、但是、因为、所以、如果、虽然。连词本身没有实在意义，只起连接作用；它连接的两部分在逻辑上是并列或有关系，不是修饰关系。","怎么认":["是不是在连接两个词、短语或句子？“苹果和香蕉、虽然累但是坚持”里的“和、虽然……但是”就是连词。","连接的两个部分能不能换位置？并列连词连接的部分换位置意思基本不变。","删掉它试试：删掉连词，两部分就散了，关系也看不出来了。"],"辨析":"连词和介词最容易混，关键看换位：连词“和”连接的“老师和同学”可以换成“同学和老师”，意思不变；介词引出的对象换位置意思就变了，如“他向老师请教”不能随便换成“老师向他请教”。","例句解析":[{"句":"老师和同学一起打扫教室。","析":"“和”是连词，连接“老师”和“同学”，两个都是打扫的人，地位平等。"},{"句":"虽然下雨，但是运动会照常进行。","析":"“虽然……但是”是一对连词，连接两个分句，表示转折关系。"}],"练习":[{"q":"下面哪个词是连词？","options":["在","和","的","很"],"answer":1,"解析":"“和”连接两个词，是连词；“在”是介词，“的”是助词，“很”是副词。"},{"q":"“苹果和香蕉”换成“香蕉和苹果”，意思？","options":["变了","基本不变","变成介词","不能换"],"answer":1,"解析":"并列连词连接的部分换位置，意思基本不变。"},{"q":"“虽然……但是”表示？","options":["因果","转折","并列","选择"],"answer":1,"解析":"“虽然……但是”表示转折关系。"}],"图示":"<svg viewBox=\"0 0 30 30\" width=\"44\" height=\"44\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"3\" y=\"10\" width=\"24\" height=\"10\" rx=\"2\" fill=\"#ec407a\"/></svg><div style=\"font-size:12px;color:#888;text-align:center\">蒙特梭利符号：粉长方</div>"},{"name":"助词","例子":["的、地、得（结构助词）","了、着、过（动态助词）","吗、呢（语气助词）","妈妈做的饭真好吃","我的书、红红的苹果（的）","快地跑、认真地写（地）","跑得快、写得好（得）","吃了、看着、去过（了、着、过）","好吗、走吧（吗、吧）","的、地、得分工要记牢"],"口诀":"的定地状得后补，时态语气也清楚","易错":"“的地得”用法：“的”定语、“地”状语、“得”补语","讲解":"附着在词、短语后表示语法意义的词","深讲":"助词附着在词、短语或句子后面，起结构、动态或语气作用，本身没有实在意义。分结构助词（的、地、得）、动态助词（了、着、过）、语气助词（吗、呢、吧、啊）。助词不能单独作句子成分，要和前面的词一起看。","怎么认":["是不是附在别的词后面？“我的、快地、跑得快、吃了、好吗”里的“的、地、得、了、吗”就是助词。","删掉它试试：删掉助词，句子主干还在，但结构关系或语气就不清楚了。","“的、地、得”分工：的后跟名词，地后跟动词、形容词，得后跟补充说明。"],"辨析":"助词和语气词、叹词别混：语气词是助词里的一小类，只在句末表语气；叹词是独立成句的感叹词，多在句首。助词“了”表完成或变化，“着”表持续，“过”表经历，三者不能互换。","例句解析":[{"句":"红红的苹果真好吃。","析":"“的”是结构助词，连接定语“红红”和名词“苹果”。"},{"句":"他吃过北京烤鸭。","析":"“过”是动态助词，放在动词“吃”后面，表示曾经有过的经历。"}],"练习":[{"q":"“快地跑”中，“地”是？","options":["介词","结构助词","副词","连词"],"answer":1,"解析":"“地”连接状语和动词，是结构助词。"},{"q":"“吃了饭”中，“了”表示？","options":["持续","经历","完成","疑问"],"answer":2,"解析":"动词后的“了”表示动作完成。"},{"q":"下面哪个是语气助词？","options":["的","着","吗","得"],"answer":2,"解析":"“吗”在句末表示疑问语气，是语气助词。"}],"图示":"<svg viewBox=\"0 0 30 30\" width=\"44\" height=\"44\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"15\" cy=\"15\" r=\"5\" fill=\"#78909c\"/></svg><div style=\"font-size:12px;color:#888;text-align:center\">蒙特梭利符号：灰小圆</div>"},{"name":"语气词","例子":["吗、呢、吧、啊","明天一起去打球吧！","好吗、吃饭了吗（吗）","一起去吧、走吧（吧）","你呢、他呢（呢）","真美啊、好啊（啊）","走吧是商量、走吗是提问","语气词在句末"],"口诀":"句尾表语气，吗呢吧啊","易错":"语气词不重读","讲解":"表示语气，常用在句尾的词","深讲":"语气词用在句末，表示陈述、疑问、祈使、感叹等语气。常见语气词有吗、呢、吧、啊、呀、么。语气词不表示实在意义，读起来语气不同，意思和态度就不同：说“走吧”是商量，说“走吗”是提问。","怎么认":["是不是在句末？句末的“吗、呢、吧、啊”多半是语气词。","换一个语气词试试：把“好吗”换成“好吧”，句子从提问变成了商量，说明语气词管的是语气。","删掉它试试：删掉语气词，句子意思还在，但语气、态度就没了。"],"辨析":"语气词和叹词都和语气有关，但语气词在句末、附着在句子上；叹词独立成句、多在句首。“啊，真美！”里的“啊”是叹词；“这花真美啊”里的“啊”是语气词。","例句解析":[{"句":"我们一起去公园吧。","析":"句末的“吧”是语气词，表示商量、建议。"},{"句":"你吃饭了吗？","析":"句末的“吗”是语气词，把陈述句变成了疑问句。"}],"练习":[{"q":"“一起去吧”中，“吧”是？","options":["动词","语气词","叹词","名词"],"answer":1,"解析":"句末的“吧”表示商量语气，是语气词。"},{"q":"语气词一般在？","options":["句首独立","句末","动词前","名词后"],"answer":1,"解析":"语气词用在句末，表示全句的语气。"},{"q":"“好吗”换成“好吧”，变的是？","options":["主语","语气","宾语","时间"],"answer":1,"解析":"换语气词，句子意思基本不变，变的是语气和态度。"}],"图示":"<svg viewBox=\"0 0 30 30\" width=\"44\" height=\"44\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"15\" cy=\"15\" r=\"9\" fill=\"none\" stroke=\"#f9a825\" stroke-width=\"3\"/></svg><div style=\"font-size:12px;color:#888;text-align:center\">蒙特梭利符号：金环</div>"},{"name":"叹词","例子":["啊、哎、哦、喂","哎呀，我忘带作业了！","啊，真美（感叹）","喂，你好（呼唤）","嗯，知道了（应答）","哈哈，真有趣（笑声）","哎呀，疼死我了","啊在句首是叹词、在句末是语气词"],"口诀":"感叹呼唤应答，叹词来表达","易错":"叹词常独立成句，后用逗号或感叹号","讲解":"表示感叹、呼唤、应答的词","深讲":"叹词表示感叹、呼唤、应答等，独立成句或独立成分，常常在句首，后面常带感叹号或逗号。常见叹词有啊、哎呀、哦、喂、嗯、哈哈。叹词不作句子的主要成分，删掉它，句子主干还在，只是感情色彩弱了。","怎么认":["是不是独立在句首、后面有感叹号或逗号？“啊，真美！喂，你好！”里的“啊、喂”就是叹词。","是不是在表示感叹、呼唤或应答？是的，多半是叹词。","删掉它试试：删掉叹词，句子还能成立，只是少了那股感情劲儿。"],"辨析":"叹词和语气词最容易混：叹词独立、多在句首（“啊，真美！”）；语气词附着在句末（“真美啊！”）。同一个“啊”字，位置不同，词类就不同——这正是“看位置、看作用”的好例子。","例句解析":[{"句":"啊，祖国的山河真壮丽！","析":"句首的“啊”是叹词，独立成成分，表达赞叹，后面用逗号隔开。"},{"句":"喂，你听见了吗？","析":"“喂”是叹词，表示呼唤，引起对方注意；句末的“吗”才是语气词。"}],"练习":[{"q":"“哎呀，疼死我了！”中，“哎呀”是？","options":["语气词","叹词","副词","形容词"],"answer":1,"解析":"句首独立的“哎呀”表示感叹，是叹词。"},{"q":"叹词常常在？","options":["句末","句首独立","动词后","名词前"],"answer":1,"解析":"叹词独立成句或成分，常常在句首。"},{"q":"“真美啊”中，“啊”是？","options":["叹词","语气词","动词","介词"],"answer":1,"解析":"句末的“啊”附着在句子上表语气，是语气词，不是叹词。"}],"图示":"<svg viewBox=\"0 0 30 30\" width=\"44\" height=\"44\" xmlns=\"http://www.w3.org/2000/svg\"><polygon points=\"15,4 20,15 15,26 10,15\" fill=\"#f9a825\"/></svg><div style=\"font-size:12px;color:#888;text-align:center\">蒙特梭利符号：金菱</div>"}],"name":"词的分类（12类）"},{"id":"duanyu","items":[{"name":"并列式","例子":["老师和同学","又高又大","调查研究","爸爸和妈妈"],"口诀":"地位平等是并列","易错":"“和”连接的也可能是介词短语，要看语境","讲解":"前后成分地位平等，无主次之分"},{"name":"偏正式","例子":["红旗（定中）","认真学习（状中）","伟大的祖国","漂亮的新书包"],"口诀":"前偏后正，修饰中心","易错":"是短语中数量最多的一种","讲解":"前偏后正，修饰限制关系"},{"name":"主谓式","例子":["祖国繁荣","他来了","天气晴朗","小鸟唱歌"],"口诀":"谁怎么样，主谓来讲","易错":"主谓短语可作主语、宾语、定语","讲解":"陈述关系，前后可加“是”"},{"name":"动宾式","例子":["学习语文","打扫教室","热爱祖国","踢足球"],"口诀":"动词在前，宾语在后","易错":"不及物动词不能带宾语（如“出发”不能直接带宾语）","讲解":"支配关系，动词+受动者"},{"name":"补充式","例子":["写得好","跑得快","热极了","笑得很开心"],"口诀":"补充说明在后头","易错":"常由“得”字连接","讲解":"后补前，补充说明动作结果/程度"}],"name":"短语的结构（5种）"},{"id":"juzichengfen","items":[{"name":"主语","例子":["〔他〕来了","〔祖国的明天〕会更好","〔小明〕在踢球"],"口诀":"主语回答谁什么","易错":"主语多余或残缺是常见病句","讲解":"谓语陈述的对象，回答“谁/什么”","类比":"主语就像电影的\"主角\"：一句话讲谁，ta 就是主语。","图示":"<svg viewBox=\"0 0 400 80\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"30\" y1=\"40\" x2=\"370\" y2=\"40\" stroke=\"#333\" stroke-width=\"2\"/><text x=\"60\" y=\"32\" font-size=\"15\">主语</text><text x=\"180\" y=\"32\" font-size=\"15\">‖</text><text x=\"210\" y=\"32\" font-size=\"15\">谓语</text><text x=\"60\" y=\"65\" font-size=\"12\" fill=\"#888\">黎锦熙图解：主谓宾在线上，定状补在线下</text></svg>"},{"name":"谓语","例子":["他〔来了〕","祖国〔是花园〕","小狗〔汪汪叫〕"],"口诀":"谓语说明怎么样","易错":"谓语残缺会导致句子不完整","讲解":"陈述主语，回答“怎么样/是什么/做什么”","类比":"谓语就像主角的\"动作戏\"：主角在干什么，谓语就讲什么。"},{"name":"宾语","例子":["学习〔语文〕","热爱〔祖国〕","我爱〔妈妈〕"],"口诀":"动词之后找宾语","易错":"及物动词缺宾语是成分残缺","讲解":"动作的对象，回答“谁/什么”","类比":"宾语就像动作的\"接球手\"：动词这个球扔出去，砸到谁，谁就是宾语。"},{"name":"定语","例子":["（红色的）旗","（我）的书","（粉色的）铅笔盒"],"口诀":"定语修饰名词，常带“的”字","易错":"多重定语语序：领属+数量+动词性+形容词性+名词","讲解":"修饰名词，回答“什么样的”","类比":"定语就像\"标签\"：贴在名词前面，告诉你这是哪一个。"},{"name":"状语","例子":["〔认真地〕学习","〔在教室里〕读书","〔高兴地〕跳起来"],"口诀":"状语修饰动形，常带“地”字","易错":"状语位置一般在谓语前","讲解":"修饰动词/形容词，回答“怎样/何时/何地”","类比":"状语就像\"滤镜\"：加在动词/形容词前面，告诉你动作怎么发生的。"},{"name":"补语","例子":["写得〔好〕","跑得〔快〕","写得〔很工整〕"],"口诀":"补语补充在后头，常带“得”字","易错":"“得”后补语与“地”前状语不要混","讲解":"补充说明谓语，回答“到什么程度/结果”","类比":"补语就像\"赛后采访\"：动作结束了，补一句\"结果如何\"。"}],"name":"单句的成分（6种）"},{"id":"fuju","items":[{"name":"并列复句","例子":["他来了，我也来了","我写作业，弟弟看书"],"口诀":"关联词：既……又、也、还","易错":"","讲解":"分句间平等并列"},{"name":"递进复句","例子":["他不但会唱歌，而且会跳舞","她不但画画好，而且字也写得漂亮"],"口诀":"关联词：不但……而且、甚至","易错":"递进顺序不能颠倒","讲解":"后分句比前分句更进一层"},{"name":"选择复句","例子":["是去还是留，你定吧","放学后去打球还是回家，你选吧"],"口诀":"关联词：或者……或者、是……还是","易错":"“或者”表选择，“还是”用于问句","讲解":"列出两种情况供选择"},{"name":"转折复句","例子":["虽然下雨，但是没耽误","虽然我很累，但是我坚持跑完了"],"口诀":"关联词：虽然……但是、尽管……还是","易错":"转折连词不能单独省略后半","讲解":"前后意思相反或相对","类比":"转折就像\"先扬后抑\"：前面夸一句，后面\"但是\"一转才是真心话。","图示":"<svg viewBox=\"0 0 320 160\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">转折复句：意思拐了个弯</text><text x=\"12\" y=\"44\" font-size=\"15\" class=\"svg-ink\">虽然他生病了，</text><text x=\"117\" y=\"44\" font-size=\"15\" class=\"svg-red\">但是</text><text x=\"147\" y=\"44\" font-size=\"15\" class=\"svg-ink\">还是来了。</text><path d=\"M30,80 L170,80 Q200,80 200,110 L200,132\" stroke-width=\"12\" fill=\"none\" stroke-linecap=\"round\" opacity=\"0.3\"/ class=\"svg-muted-s\"><circle r=\"6\" class=\"svg-accent\"><animateMotion dur=\"6s\" repeatCount=\"indefinite\" path=\"M30,80 L170,80 Q200,80 200,110 L200,132\"/></circle><text x=\"212\" y=\"100\" font-size=\"12\" class=\"svg-red\">拐弯！</text><text x=\"12\" y=\"150\" font-size=\"12\" class=\"svg-muted\">\"虽然\"先让步，\"但是\"后面才是真正想说的</text></svg>"},{"name":"因果复句","例子":["因为努力，所以成功","因为我生病了，所以没去上学"],"口诀":"关联词：因为……所以、由于","易错":"因果倒置会造成逻辑错误","讲解":"前因后果","类比":"因果就像\"多米诺\"：前一张牌倒了（因），后一张跟着倒（果）。","图示":"<svg viewBox=\"0 0 320 150\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">因果复句：原因 → 结果</text><rect x=\"12\" y=\"36\" width=\"120\" height=\"44\" rx=\"10\" fill=\"none\" stroke-width=\"2\" class=\"svg-accent-s\"><animate attributeName=\"opacity\" values=\"1;1;0.35;0.35;1\" keyTimes=\"0;0.45;0.5;0.95;1\" dur=\"8s\" repeatCount=\"indefinite\"/></rect><text x=\"72\" y=\"63\" font-size=\"15\" text-anchor=\"middle\" class=\"svg-ink\">因为下雨了</text><line x1=\"136\" y1=\"58\" x2=\"184\" y2=\"58\" stroke-width=\"2\"/ class=\"svg-muted-s\"><circle r=\"5\" class=\"svg-accent\"><animateMotion dur=\"2s\" repeatCount=\"indefinite\" path=\"M136,58 L184,58\"/></circle><polygon points=\"184,58 176,53 176,63\"/ class=\"svg-accent\"><rect x=\"188\" y=\"36\" width=\"120\" height=\"44\" rx=\"10\" fill=\"none\" stroke-width=\"2\" class=\"svg-red-s\"><animate attributeName=\"opacity\" values=\"0.35;0.35;1;1;0.35\" keyTimes=\"0;0.45;0.5;0.95;1\" dur=\"8s\" repeatCount=\"indefinite\"/></rect><text x=\"248\" y=\"63\" font-size=\"15\" text-anchor=\"middle\" class=\"svg-ink\">所以没去踢球</text><text x=\"12\" y=\"122\" font-size=\"12\" class=\"svg-muted\">金点从原因流向结果：\"因为\"和\"所以\"是固定搭档</text></svg>"},{"name":"假设复句","例子":["如果下雨，就不去了","如果周末不下雨，我们就去爬山"],"口诀":"关联词：如果……就、假如","易错":"假设与条件的区别：假设多为未然","讲解":"假设条件下的结果"},{"name":"条件复句","例子":["只有努力，才能成功","只有多练习，才能写好字"],"口诀":"关联词：只有……才、只要……就","易错":"“只有……才”表必要条件，“只要……就”表充分条件","讲解":"条件与结果"}],"name":"复句的类型（7种）"},{"id":"guanlianci","name":"关联词（10组）","items":[{"name":"因为…所以…","讲解":"表示因果关系：前因后果。","例子":["因为下雨，所以运动会取消了","因为他努力，所以考了第一"],"口诀":"前因后果","易错":"不能说“因为…但是…”"},{"name":"如果…就…","讲解":"表示假设：假设条件下的结果。","例子":["如果明天下雨，我们就不去春游了","如果你来，我就告诉你"],"口诀":"假设条件","易错":"假设多为还没发生的事"},{"name":"虽然…但是…","讲解":"表示转折：前后意思相反或相对。","例子":["虽然下雨了，但是我们照常上课","虽然他很累，但是坚持跑完了"],"口诀":"先让后转","易错":"前后意思要相反或相对"},{"name":"不但…而且…","讲解":"表示递进：后分句比前分句更进一层。","例子":["他不但学习好，而且爱运动","她不但画画好，而且字也写得漂亮"],"口诀":"层层递进","易错":"递进顺序不能颠倒"},{"name":"只有…才…","讲解":"表示必要条件：缺了这个条件就不行。","例子":["只有努力，才能成功","只有多练习，才能写好字"],"口诀":"必要条件","易错":"别和“只要…就…”搞混（那是充分条件）"},{"name":"无论…都…","讲解":"表示无条件：不管什么情况，结果都一样。","例子":["无论刮风下雨，他都按时到校","无论谁问，他都不说"],"口诀":"条件再多都不怕","易错":"“无论”后可跟疑问词：无论谁/哪儿/什么"},{"name":"既…又…","讲解":"表示并列：两个方面同时成立。","例子":["他既聪明又勤奋","这件衣服既好看又便宜"],"口诀":"两个优点一起夸","易错":"前后感情色彩要一致（不能既好又坏）"},{"name":"不是…而是…","讲解":"表示选择：否定前者，肯定后者。","例子":["他不是不认真，而是方法不对","我不是不想去，而是有事"],"口诀":"否定一个，肯定一个","易错":"前后要是同一类事物才能这样选"},{"name":"先…然后…","讲解":"表示承接：按顺序做事情。","例子":["先洗手，然后吃饭","先写作业，然后才能看电视"],"口诀":"事情有先后","易错":"顺序不能乱，先做的放前面"},{"name":"一…就…","讲解":"表示紧接：两个动作挨得很紧。","例子":["我一回家就写作业","他一听音乐就开心"],"口诀":"紧接着发生","易错":"“一…就…”中间别加太多字"}]},{"id":"xiuci","items":[{"name":"比喻","例子":["他像豹子一样快","天上的云像棉花糖"],"口诀":"生动形象","易错":"有“像”不一定是比喻（如表示举例）","讲解":"打比方，生动形象","图示":"<svg viewBox=\"0 0 320 160\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">比喻：本体＋喻词＋喻体，三件套</text><text x=\"12\" y=\"42\" font-size=\"11\" class=\"svg-accent\">本体<animate attributeName=\"opacity\" values=\"1;1;0.35;0.35;1\" keyTimes=\"0;0.3;0.33;0.97;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"105\" y=\"42\" font-size=\"11\" class=\"svg-accent\">喻词<animate attributeName=\"opacity\" values=\"0.35;0.35;1;1;0.35;0.35\" keyTimes=\"0;0.3;0.33;0.6;0.63;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"130\" y=\"42\" font-size=\"11\" class=\"svg-accent\">喻体<animate attributeName=\"opacity\" values=\"0.35;0.35;0.35;1;1;0.35\" keyTimes=\"0;0.6;0.63;0.9;0.93;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"12\" y=\"70\" font-size=\"17\" class=\"svg-ink\">弯弯的月儿</text><text x=\"105\" y=\"70\" font-size=\"17\" class=\"svg-accent\">像<animate attributeName=\"opacity\" values=\"1;1;1;1;1;1\" keyTimes=\"0;0.3;0.33;0.6;0.63;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"130\" y=\"70\" font-size=\"17\" class=\"svg-ink\">小小的船</text><path d=\"M45,86 Q110,112 180,86\" stroke-width=\"1.5\" fill=\"none\" stroke-dasharray=\"4,3\"/ class=\"svg-muted-s\"><circle r=\"4\" class=\"svg-accent\"><animateMotion dur=\"3s\" repeatCount=\"indefinite\" path=\"M45,86 Q110,112 180,86\"/></circle><text x=\"12\" y=\"140\" font-size=\"12\" class=\"svg-muted\">月儿（本体）像（喻词）小船（喻体），金点来回穿梭</text></svg>"},{"name":"拟人","例子":["小草向我点头","风儿轻轻地抚摸着我的脸"],"口诀":"赋予情感","易错":"拟人与比喻可兼用","讲解":"把物当人写"},{"name":"夸张","例子":["白发三千丈","教室里安静得连针掉地上都听得见"],"口诀":"突出强调","易错":"夸张要合理，不能失真","讲解":"故意夸大或缩小"},{"name":"排比","例子":["爱心是春风，是夏雨，是秋月","春天是花朵，是绿叶，是暖阳"],"口诀":"增强气势","易错":"排比项数一般三项以上","讲解":"三个以上结构相似的句子"},{"name":"对偶","例子":["横眉冷对千夫指，俯首甘为孺子牛","书山有路勤为径，学海无涯苦作舟"],"口诀":"整齐凝练","易错":"对偶要求平仄相对（宽对可放宽）","讲解":"字数相等、结构相同、意义相关"},{"name":"反复","例子":["盼望着，盼望着，春天来了","加油，加油，我们一定能赢！"],"口诀":"强调加深","易错":"与排比区别：反复是重复同一内容","讲解":"重复词语/句子强调"},{"name":"设问","例子":["是谁创造了世界？是我们劳动群众","谁是班上跑得最快的？是小明"],"口诀":"引起注意","易错":"设问后一定要回答","讲解":"自问自答"},{"name":"反问","例子":["这不是很清楚吗？","这么简单的题，你不会做吗？"],"口诀":"加强语气","易错":"反问后不回答，答案隐含其中","讲解":"用问句表肯定/否定，加强语气"}],"name":"常见修辞格（8种）"},{"id":"bingju","items":[{"name":"语序不当","例子":["病：他把教室打扫得干干净净、整整齐齐→改：把“整整齐齐”删去或调整","病：我昨天晚上把作业认真地写完了 → 改：我昨天晚上认真地把作业写完了"],"口诀":"先找主干，再看修饰","易错":"多重定语/状语语序是重灾区","讲解":"词语或分句顺序颠倒","类比":"语序不当就像\"穿反了衣服\"：每件都在，但位置错了。"},{"name":"搭配不当","例子":["病：他怀着崇高的心情→改：怀着激动的心情","病：同学们都很爱护 → 改：同学们都很爱护公物"],"口诀":"主谓动宾，一一对应","易错":"“怀着……心情”不能配“崇高”","讲解":"主谓、动宾、修饰语与中心词不搭配","类比":"搭配不当就像\"左脚穿右脚的鞋\"：单个看都对，放一起别扭。"},{"name":"成分残缺或赘余","例子":["病：通过学习，使我进步（缺主语）→删“使”","病：不约而同异口同声（赘余）","病：通过努力，取得了进步 → 改：通过努力，我取得了进步"],"口诀":"压缩主干，残缺立现","易错":"“通过……使”句式最易缺主语","讲解":"缺主/谓/宾，或词语重复多余"},{"name":"结构混乱","例子":["病：原因是由于他努力→改：原因是他努力","病：这次活动是受到了大家的欢迎造成的 → 改：这次活动受到了大家的欢迎"],"口诀":"两种句式，留一去一","易错":"“原因是由于”“是由于……造成的”典型杂糅","讲解":"句式杂糅，两种结构纠缠"},{"name":"表意不明","例子":["病：他背着总经理和副总喝酒（谁喝？）","病：小红的妈妈说她病了（谁病了？）"],"口诀":"代词指代要明确","易错":"多重定语易生歧义","讲解":"歧义或指代不清"},{"name":"不合逻辑","例子":["病：三月的南京是美丽的季节（主谓不合逻辑）","病：他七点起床洗漱，然后六点半出门（时间倒流了！）"],"口诀":"概念关系要理清","易错":"“美”和“季节”不能搭配","讲解":"自相矛盾、概念并列不当等"},{"name":"主语残缺","讲解":"滥用介词（通过/使/令）导致主语丢失，话没了“头”。","例子":["病：通过这次春游，使我增长了见识 → 改：删去“使”","病：看了这部电影，受到了教育 → 改：我受到了教育"],"口诀":"通过使令，删一留一","易错":"“通过……使……”是重灾区","类比":"主语残缺就像“没头的话”：说了半天，不知道谁干的。"},{"name":"谓语残缺","讲解":"只有主语没有谓语，话没说完。","例子":["病：他昨天 → 改：他昨天来了","病：我们班的同学都很 → 改：我们班的同学都很好学"],"口诀":"主语有了，动作要有","易错":"压缩句子后只剩主语，就是谓语残缺"},{"name":"宾语残缺","讲解":"及物动词后缺宾语，动作没“着落”。","例子":["病：我们要养成的好习惯 → 改：养成讲卫生的好习惯","病：大家都喜欢 → 改：大家都喜欢这本书"],"口诀":"动词之后，宾语莫丢","易错":"“养成”“喜欢”后不能空着"},{"name":"定语语序不当","讲解":"多重定语排列顺序错误。","例子":["病：一位优秀的我们班的学生 → 改：我们班的一位优秀的学生"],"口诀":"谁的、多少、干啥、啥样，依次排好","易错":"顺序：领属＋数量＋动词性＋形容词性＋名词"},{"name":"关联词误用","讲解":"关联词前后不搭配，张冠李戴。","例子":["病：因为他很努力，但是没考好 → 改：虽然他很努力，但是没考好","病：只有下雨，就不去 → 改：只要下雨，就不去"],"口诀":"因果转折，配对要准","易错":"“因为”配“所以”，“虽然”配“但是”，别串门","图示":"<svg viewBox=\"0 0 320 150\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">关联词误用：\"因为\"不能配\"但是\"</text><g opacity=\"1\"><animate attributeName=\"opacity\" values=\"1;1;0;0;1;1\" keyTimes=\"0;0.4;0.5;0.9;0.95;1\" dur=\"8s\" repeatCount=\"indefinite\"/><text x=\"12\" y=\"64\" font-size=\"16\" class=\"svg-ink\">因为下雨，</text><text x=\"92\" y=\"64\" font-size=\"16\" class=\"svg-red\">但是</text><text x=\"124\" y=\"64\" font-size=\"16\" class=\"svg-ink\">没带伞。</text><text x=\"280\" y=\"64\" font-size=\"20\" class=\"svg-red\">✗</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;0;1;1;0;0\" keyTimes=\"0;0.4;0.5;0.9;0.95;1\" dur=\"8s\" repeatCount=\"indefinite\"/><text x=\"12\" y=\"64\" font-size=\"16\" class=\"svg-ink\">因为下雨，</text><text x=\"92\" y=\"64\" font-size=\"16\" class=\"svg-accent\">所以</text><text x=\"124\" y=\"64\" font-size=\"16\" class=\"svg-ink\">没带伞。</text><text x=\"280\" y=\"64\" font-size=\"20\" class=\"svg-accent\">✓</text></g><text x=\"12\" y=\"122\" font-size=\"12\" class=\"svg-muted\">因为…所以…／虽然…但是…，前后要配套</text></svg>"},{"name":"关联词残缺","讲解":"关联词只说一半，另一半丢了。","例子":["病：他一边跑步，听音乐 → 改：他一边跑步，一边听音乐","病：虽然天气冷，坚持锻炼 → 改：虽然天气冷，但是坚持锻炼"],"口诀":"关联成双，缺一不可","易错":"“一边…一边…”“虽然…但是…”都要说全"},{"name":"指代不明","讲解":"代词指代对象不明确，不知道说的是谁。","例子":["病：小明和小刚说，他赢了 → 改：小明对小刚说：“我赢了”","病：他把书放在桌子上，它不见了 → 改：书不见了"],"口诀":"他她它，谁是谁","易错":"两个人以上时，少用“他”，直接叫名字"},{"name":"前后矛盾","讲解":"前后说法自相矛盾，自己打自己。","例子":["病：他断定这次大概能考第一 → 改：他估计这次能考第一","病：昨天上午，我亲眼看见他下午在打球（时间打架了！）"],"口诀":"断定别大概，前后别打架","易错":"“断定”“肯定”后不能跟“大概”“可能”"},{"name":"并列概念交叉","讲解":"并列的概念有交叉或包含关系，不能放一排。","例子":["病：水果、苹果和香蕉都很好吃 → 改：苹果和香蕉都很好吃","病：他喜欢球类、足球和音乐 → 改：他喜欢足球和音乐"],"口诀":"大概念小概念，别放一排","易错":"“水果”包含了“苹果”，不能并列"},{"name":"重复啰嗦","讲解":"词语意思重复，多余。","例子":["病：他凯旋归来了 → 改：他凯旋了（“旋”就是归来）","病：非常十分开心 → 改：非常开心"],"口诀":"意思重复，删去一个","易错":"“凯旋”本身就含“归来”意"},{"name":"约数矛盾","讲解":"约数词叠用，自相矛盾。","例子":["病：大约有30人左右 → 改：大约有30人","病：最少也有10多个 → 改：有10多个"],"口诀":"大约左右，留一个就够","易错":"“大约”“左右”“上下”“多”都是约数，别叠用"},{"name":"否定失当","讲解":"多重否定算错了账，表意正好相反。","例子":["病：为了避免不再犯错，我们要认真 → 改：为了避免犯错","病：切忌不要骄傲 → 改：切忌骄傲"],"口诀":"否定加否定，意思要算清","易错":"“避免”“切忌”“防止”后不再加“不”"},{"name":"主谓搭配不当","讲解":"主语和谓语搭配不起来，对不上号。","例子":["病：我国的人口是世界上最多的国家 → 改：我国是世界上人口最多的国家"],"口诀":"谁是什么，对号入座","易错":"“人口”不能是“国家”，主语谓语要门当户对"},{"name":"动宾搭配不当","讲解":"动词和宾语不搭配。","例子":["病：我们要端正学习 → 改：端正学习态度","病：他发扬了球技 → 改：他提高了球技"],"口诀":"动词宾语，手拉手配对","易错":"“端正”配“态度”，“提高”配“水平”，别拉错手"}],"name":"常见病句类型（20种）"},{"id":"gaoji","name":"高级句式（7种）","items":[{"name":"把字句","类比":"把字句就像\"抓娃娃机\"：先\"把\"娃娃抓住（提起宾语），再决定怎么处置它。","图示":"<svg viewBox=\"0 0 320 150\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">把字句：动作的对象提前了</text><text x=\"12\" y=\"44\" font-size=\"13\" class=\"svg-muted\">普通句：我 吃了 苹果</text><text x=\"12\" y=\"84\" font-size=\"18\" class=\"svg-ink\">我</text><text x=\"48\" y=\"84\" font-size=\"18\" class=\"svg-accent\" opacity=\"0\">把<animate attributeName=\"opacity\" values=\"0;0;1;1;1;0\" keyTimes=\"0;0.2;0.4;0.8;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><text x=\"140\" y=\"84\" font-size=\"18\" class=\"svg-ink\">吃了</text><text x=\"92\" y=\"84\" font-size=\"18\" class=\"svg-accent\">苹果<animate attributeName=\"x\" values=\"196;196;92;92;196;196\" keyTimes=\"0;0.2;0.4;0.8;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><path d=\"M214,66 Q160,44 112,66\" stroke-width=\"1.5\" fill=\"none\" stroke-dasharray=\"4,3\" opacity=\"0\" class=\"svg-accent-s\"><animate attributeName=\"opacity\" values=\"0;0;0.9;0.9;0.9;0\" keyTimes=\"0;0.2;0.4;0.8;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></path><polygon points=\"112,66 122,62 120,72\" class=\"svg-accent\" opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;0;0.9;0.9;0.9;0\" keyTimes=\"0;0.2;0.4;0.8;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></polygon><text x=\"12\" y=\"122\" font-size=\"12\" class=\"svg-muted\">苹果从\"吃了\"后面搬到\"把\"后面，动作对象被提前</text></svg>","动画":{"steps":[{"tokens":["我","吃","了","苹果"],"note":"正常语序：我吃了苹果"},{"tokens":["我","把","苹果","吃","了"],"note":"\"把\"提起宾语，放到动词前"},{"tokens":["我","把","苹果","吃","完","了"],"note":"动词后要有\"着落\"（完/掉/干净），不能光秃秃"}]},"讲解":"把宾语提前到动词前，强调对宾语的处置。公式：主语＋把＋宾语＋动词＋补语/了。","口诀":"把字提起宾，动词要有根（补语）","例子":["我把作业写完了","他把杯子打碎了","妈妈把房间收拾干净了"],"易错":"✗ 我把书看（动词光秃秃） ✓ 我把书看完了；心理动词（喜欢/觉得）不能用把字句","小测":[{"q":"哪句把字句正确？","options":["我把饭吃","我把饭吃完了","我把饭吃着"],"answer":1,"解析":"动词后要有补语或\"了\"表结果。"},{"q":"\"他喜欢音乐\"能改把字句吗？","options":["他把音乐喜欢了","不能改","他把音乐喜欢着"],"answer":1,"解析":"\"喜欢\"无处置义，不能用把。"}]},{"name":"被字句","类比":"被字句就像\"领奖台\"：动作的承受者站上主语位，强调它\"遭了什么\"。","动画":{"steps":[{"tokens":["小狗","咬","了","小明"],"note":"主动句：小狗是施事"},{"tokens":["小明","被","小狗","咬","了"],"note":"小明变主语，强调他的遭遇"},{"tokens":["小明","被","咬","伤","了"],"note":"\"被\"后施事可省，结果\"伤\"不能省"}]},"讲解":"主语是动作的承受者。公式：受事＋被/叫/让＋施事＋动词＋补语。","口诀":"被字一出，受害现身","例子":["小明被小狗咬了","杯子被打碎了","我的气球被风吹走了"],"易错":"✗ 他被吃了饭 ✓ 他被批评了；\"被\"后多为不如意事","小测":[{"q":"被字句强调？","options":["谁做的","主语遭受了什么","动作多快"],"answer":1,"解析":"主语是受事，强调遭遇。"}],"图示":"<svg viewBox=\"0 0 320 150\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">被字句：被咬的坐上了主语位</text><text x=\"12\" y=\"44\" font-size=\"13\" class=\"svg-muted\">主动句：小狗 咬了 小明</text><text x=\"60\" y=\"84\" font-size=\"18\" class=\"svg-accent\" opacity=\"0\">被<animate attributeName=\"opacity\" values=\"0;0;1;1;1;0\" keyTimes=\"0;0.2;0.4;0.8;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><text x=\"168\" y=\"84\" font-size=\"18\" class=\"svg-ink\">咬了</text><text x=\"12\" y=\"84\" font-size=\"18\" class=\"svg-accent\">小明<animate attributeName=\"x\" values=\"240;240;12;12;240;240\" keyTimes=\"0;0.2;0.4;0.8;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><text x=\"96\" y=\"84\" font-size=\"18\" class=\"svg-ink\">小狗<animate attributeName=\"x\" values=\"12;12;96;96;12;12\" keyTimes=\"0;0.2;0.4;0.8;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><text x=\"12\" y=\"122\" font-size=\"12\" class=\"svg-muted\">小明、小狗位置互换：谁被咬，一目了然</text></svg>"},{"name":"存现句","类比":"存现句就像\"监控画面\"：某地（出现了/消失了）某物，讲的是\"有无\"，不是\"谁干了什么\"。","讲解":"表示某处存在、出现、消失某人/物。公式：处所＋动词＋人/物。如\"门口站着一个人\"。","口诀":"哪里有啥，存现回答","例子":["天上掉下个馅饼","屋里走出一位老人","黑板上写着几个大字"],"易错":"存现句的动词多为\"有/站/坐/来/去\"，主语是处所不是人","小测":[{"q":"哪句是存现句？","options":["我看见一个人","门口站着一个人","一个人站在门口"],"answer":1,"解析":"主语是处所\"门口\"，表存在。"}],"图示":"<svg viewBox=\"0 0 420 110\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"20\" y=\"20\" width=\"100\" height=\"60\" rx=\"8\" fill=\"#e0f2f1\" stroke=\"#00897b\" stroke-width=\"2\"/><text x=\"35\" y=\"55\" font-size=\"14\">门口</text><text x=\"140\" y=\"55\" font-size=\"16\">站着</text><circle cx=\"280\" cy=\"50\" r=\"22\" fill=\"#fff3e0\" stroke=\"#ff9800\" stroke-width=\"2\"/><text x=\"268\" y=\"57\" font-size=\"16\">人</text><text x=\"30\" y=\"100\" font-size=\"12\" fill=\"#888\">处所 ＋ 动词 ＋ 人/物（讲\"有无\"）</text></svg>"},{"name":"是…的句","类比":"是…的就像\"聚光灯\"：把\"是\"和\"的\"框住的部分照亮，强调\"就是它\"。","动画":{"steps":[{"tokens":["他","是","昨天","来","的"],"note":"强调时间：是\"昨天\"来的"},{"tokens":["他","是","坐飞机","来","的"],"note":"框住\"坐飞机\"：强调方式"},{"tokens":["他","是","北京","人"],"note":"注意：判断句\"他是北京人\"不用\"的\""}]},"讲解":"强调已发生情况的时间/方式/处所。框住被强调成分。","口诀":"是的框住，强调突出","例子":["我是昨天来的","他是坐火车走的","这本书是我昨天买的"],"易错":"只用于已发生的事；\"是…的\"中间是被强调的状语","图示":"<svg viewBox=\"0 0 420 100\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"30\" y=\"50\" font-size=\"17\">他 是 <tspan fill=\"#8e24aa\" font-weight=\"bold\">昨天</tspan> 来 的</text><rect x=\"95\" y=\"25\" width=\"60\" height=\"35\" rx=\"6\" fill=\"none\" stroke=\"#8e24aa\" stroke-width=\"2\" stroke-dasharray=\"5,3\"/><text x=\"30\" y=\"85\" font-size=\"12\" fill=\"#888\">虚线框＝聚光灯，强调框住的成分</text></svg>"},{"name":"比较句","类比":"比较句就像\"天平\"：左边放一个，右边放一个，看哪边重。","图示":"<svg viewBox=\"0 0 420 120\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"200\" y1=\"20\" x2=\"200\" y2=\"100\" stroke=\"#999\" stroke-width=\"3\"/><line x1=\"60\" y1=\"60\" x2=\"340\" y2=\"60\" stroke=\"#999\" stroke-width=\"3\"/><rect x=\"80\" y=\"60\" width=\"50\" height=\"25\" fill=\"#90caf9\"/><text x=\"88\" y=\"78\" font-size=\"13\">我</text><rect x=\"270\" y=\"35\" width=\"50\" height=\"50\" fill=\"#ef9a9a\"/><text x=\"278\" y=\"65\" font-size=\"13\">他</text><text x=\"150\" y=\"45\" font-size=\"15\">比</text><text x=\"150\" y=\"100\" font-size=\"12\" fill=\"#888\">天平：比后是参照物</text></svg>","讲解":"A 比 B ＋形容词：A 超过 B。否定用\"没有\"（我没有他高≠我比他矮）。","口诀":"比后参照，形容收尾","例子":["我比他高","今天没有昨天冷","弟弟比我高半头"],"易错":"\"没有\"表否定比较，不表反向；\"更\"表递进（更好）","小测":[{"q":"\"我没有他高\"意思是？","options":["我比他矮","我不如他高","他比我矮"],"answer":1,"解析":"\"没有\"只否定\"比他高\"，不等于反向。"}]},{"name":"双重否定","类比":"双重否定就像\"负负得正\"：两个\"不\"撞在一起，变成强烈的肯定。","讲解":"不得不＝必须；不能不＝一定要。语气比单用\"必须\"更强烈、更无奈。","口诀":"双否变肯，语气加倍","例子":["我不得不去","他不能不承认","我不得不承认他是对的"],"易错":"\"不会不\"（他不会不来＝他一定来）别和\"不\"搞混","图示":"<svg viewBox=\"0 0 320 150\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">双重否定：两个\"不\"互相抵消</text><text x=\"12\" y=\"44\" font-size=\"13\" class=\"svg-muted\">我不得不去 ＝ ?</text><text x=\"20\" y=\"84\" font-size=\"22\" class=\"svg-ink\">我</text><text x=\"92\" y=\"84\" font-size=\"22\" class=\"svg-accent\" opacity=\"1\">得<animate attributeName=\"opacity\" values=\"1;1;0;0;0;1\" keyTimes=\"0;0.3;0.45;0.9;0.95;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><text x=\"164\" y=\"84\" font-size=\"22\" class=\"svg-ink\">去</text><text x=\"56\" y=\"84\" font-size=\"22\" class=\"svg-red\">不<animate attributeName=\"x\" values=\"56;56;104;104;104;56\" keyTimes=\"0;0.3;0.45;0.9;0.95;1\" dur=\"8s\" repeatCount=\"indefinite\"/><animate attributeName=\"opacity\" values=\"1;1;1;0;0;1\" keyTimes=\"0;0.3;0.45;0.55;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><text x=\"128\" y=\"84\" font-size=\"22\" class=\"svg-red\">不<animate attributeName=\"x\" values=\"128;128;104;104;104;128\" keyTimes=\"0;0.3;0.45;0.9;0.95;1\" dur=\"8s\" repeatCount=\"indefinite\"/><animate attributeName=\"opacity\" values=\"1;1;1;0;0;1\" keyTimes=\"0;0.3;0.45;0.55;0.9;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><text x=\"56\" y=\"84\" font-size=\"22\" class=\"svg-accent\" opacity=\"0\">一定要<animate attributeName=\"opacity\" values=\"0;0;0;1;1;0\" keyTimes=\"0;0.5;0.6;0.9;0.95;1\" dur=\"8s\" repeatCount=\"indefinite\"/></text><text x=\"12\" y=\"122\" font-size=\"12\" class=\"svg-muted\">两个\"不\"飞到一起抵消 → 我一定要去（肯定）</text></svg>"},{"name":"歧义句","类比":"歧义句就像\"魔术贴\"：一句话能贴出两种意思，病句题最爱考。","动画":{"steps":[{"tokens":["咬","死","了","猎人","的","狗"],"note":"切分A：(咬死了猎人)的狗——狗咬死了猎人"},{"tokens":["咬","死","了","猎人","的","狗"],"note":"切分B：咬死了(猎人的狗)——猎人的狗被咬死了"}]},"讲解":"一句话有两种理解。消歧方法：换切分、加标点、改语序。","口诀":"两切两意，歧义现形","例子":["鸡不吃了（鸡不吃/人不吃鸡）","他走了一个小时（离开/步行）","他说他不去了（到底谁不去？）"],"易错":"病句\"表意不明\"多为歧义；改法：明确主语或加标点","小测":[{"q":"\"咬死了猎人的狗\"有几种理解？","options":["1种","2种","3种"],"answer":1,"解析":"两种切分，两种意思。"}],"图示":"<svg viewBox=\"0 0 420 120\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"30\" y=\"35\" font-size=\"16\">咬死了猎人的狗</text><rect x=\"25\" y=\"45\" width=\"150\" height=\"28\" rx=\"6\" fill=\"#e8f5e9\" stroke=\"#4caf50\"/><text x=\"32\" y=\"64\" font-size=\"13\">咬死了猎人｜的狗</text><rect x=\"25\" y=\"80\" width=\"150\" height=\"28\" rx=\"6\" fill=\"#fff3e0\" stroke=\"#ff9800\"/><text x=\"32\" y=\"99\" font-size=\"13\">咬死了｜猎人的狗</text><text x=\"200\" y=\"70\" font-size=\"12\" fill=\"#888\">两种切法，两种意思</text></svg>"}]},{"id":"xuci","name":"虚词精讲（15组）","items":[{"name":"了/着/过","类比":"\"了\"像拍照\"咔嚓\"（事成了/情况变了），\"着\"像视频\"录制中\"（持续），\"过\"像相册\"曾经\"（有过经历）。","图示":"<svg viewBox=\"0 0 320 170\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">了 / 着 / 过：一个管\"完\"，一个管\"在\"，一个管\"过\"</text><text x=\"12\" y=\"40\" font-size=\"18\" class=\"svg-accent\">着<animate attributeName=\"opacity\" values=\"1;1;0.35;0.35;1\" keyTimes=\"0;0.3;0.33;0.97;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"36\" y=\"40\" font-size=\"15\" class=\"svg-ink\">我吃着饭</text><text x=\"190\" y=\"40\" font-size=\"12\" class=\"svg-accent\">正在进行<animate attributeName=\"opacity\" values=\"1;1;0.35;0.35;1\" keyTimes=\"0;0.3;0.33;0.97;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><rect x=\"12\" y=\"48\" width=\"0\" height=\"4\" rx=\"2\" opacity=\"0.55\" class=\"svg-accent\"><animate attributeName=\"width\" values=\"0;140;140;0;0\" keyTimes=\"0;0.28;0.3;0.33;1\" dur=\"9s\" repeatCount=\"indefinite\"/></rect><text x=\"12\" y=\"76\" font-size=\"18\" class=\"svg-accent\">了<animate attributeName=\"opacity\" values=\"0.35;0.35;1;1;0.35;0.35\" keyTimes=\"0;0.3;0.33;0.6;0.63;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"36\" y=\"76\" font-size=\"15\" class=\"svg-ink\">我吃了饭</text><text x=\"190\" y=\"76\" font-size=\"12\" class=\"svg-accent\">已经完成<animate attributeName=\"opacity\" values=\"0.35;0.35;1;1;0.35;0.35\" keyTimes=\"0;0.3;0.33;0.6;0.63;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><rect x=\"12\" y=\"84\" width=\"0\" height=\"4\" rx=\"2\" opacity=\"0.55\" class=\"svg-accent\"><animate attributeName=\"width\" values=\"0;0;140;140;0;0\" keyTimes=\"0;0.31;0.33;0.58;0.63;1\" dur=\"9s\" repeatCount=\"indefinite\"/></rect><text x=\"12\" y=\"112\" font-size=\"18\" class=\"svg-accent\">过<animate attributeName=\"opacity\" values=\"0.35;0.35;0.35;1;1;0.35\" keyTimes=\"0;0.6;0.63;0.9;0.93;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"36\" y=\"112\" font-size=\"15\" class=\"svg-ink\">我吃过饭</text><text x=\"190\" y=\"112\" font-size=\"12\" class=\"svg-accent\">以前有过<animate attributeName=\"opacity\" values=\"0.35;0.35;0.35;1;1;0.35\" keyTimes=\"0;0.6;0.63;0.9;0.93;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><rect x=\"12\" y=\"120\" width=\"0\" height=\"4\" rx=\"2\" opacity=\"0.55\" class=\"svg-accent\"><animate attributeName=\"width\" values=\"0;0;140;140;0;0\" keyTimes=\"0;0.61;0.63;0.88;0.93;1\" dur=\"9s\" repeatCount=\"indefinite\"/></rect><text x=\"12\" y=\"158\" font-size=\"12\" class=\"svg-muted\">着＝正在、了＝完了、过＝有过经历</text></svg>","动画":{"steps":[{"tokens":["我","吃","了","饭"],"note":"了₁跟动词：吃完了"},{"tokens":["下","雨","了"],"note":"了₂在句末：新情况，天开始下雨"},{"tokens":["他","正","看","着","书"],"note":"着：动作持续进行中"},{"tokens":["我","去","过","北京"],"note":"过：曾经有过去北京的经历"}]},"讲解":"了₁表完成（动词后），了₂表变化（句末）；着表持续；过表经历。","口诀":"了表完成着表持续，过表曾经经历","例子":["我吃了饭/太好了","他看着书/我去过长城","我昨天去过动物园","妹妹正哭着找妈妈"],"易错":"✗ 我昨天去了北京了（了₁了₂不叠用）","小测":[{"q":"\"我吃饭了\" 的\"了\"是？","options":["了₁完成","了₂变化","都是"],"answer":1,"解析":"句末表新情况（开始吃饭/吃完），是了₂。"},{"q":"表\"曾经\"用？","options":["了","着","过"],"answer":2,"解析":"\"去过\"＝有过去的经历。"}]},{"name":"的/地/得","类比":"的像\"标签\"（贴名词），地像\"滤镜\"（修饰动作），得像\"成绩单\"（动作后打分）。","图示":"<svg viewBox=\"0 0 320 160\"><text x=\"12\" y=\"20\" font-size=\"12\" class=\"svg-muted\">的 / 地 / 得：看它后面跟什么</text><text x=\"12\" y=\"40\" font-size=\"16\" class=\"svg-ink\">美丽</text><text x=\"48\" y=\"40\" font-size=\"16\" class=\"svg-accent\">的<animate attributeName=\"opacity\" values=\"1;1;0.35;0.35;1\" keyTimes=\"0;0.3;0.33;0.97;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"68\" y=\"40\" font-size=\"16\" class=\"svg-ink\">花</text><text x=\"200\" y=\"40\" font-size=\"12\" class=\"svg-accent\">的＋名词<animate attributeName=\"opacity\" values=\"1;1;0.35;0.35;1\" keyTimes=\"0;0.3;0.33;0.97;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"12\" y=\"78\" font-size=\"16\" class=\"svg-ink\">飞快</text><text x=\"48\" y=\"78\" font-size=\"16\" class=\"svg-accent\">地<animate attributeName=\"opacity\" values=\"0.35;0.35;1;1;0.35;0.35\" keyTimes=\"0;0.3;0.33;0.6;0.63;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"68\" y=\"78\" font-size=\"16\" class=\"svg-ink\">跑</text><text x=\"200\" y=\"78\" font-size=\"12\" class=\"svg-accent\">地＋动词<animate attributeName=\"opacity\" values=\"0.35;0.35;1;1;0.35;0.35\" keyTimes=\"0;0.3;0.33;0.6;0.63;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"12\" y=\"116\" font-size=\"16\" class=\"svg-ink\">跑</text><text x=\"48\" y=\"116\" font-size=\"16\" class=\"svg-accent\">得<animate attributeName=\"opacity\" values=\"0.35;0.35;0.35;1;1;0.35\" keyTimes=\"0;0.6;0.63;0.9;0.93;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"68\" y=\"116\" font-size=\"16\" class=\"svg-ink\">快</text><text x=\"200\" y=\"116\" font-size=\"12\" class=\"svg-accent\">动词＋得＋形容词<animate attributeName=\"opacity\" values=\"0.35;0.35;0.35;1;1;0.35\" keyTimes=\"0;0.6;0.63;0.9;0.93;1\" dur=\"9s\" repeatCount=\"indefinite\"/></text><text x=\"12\" y=\"146\" font-size=\"12\" class=\"svg-muted\">的跟名词、地跟动词、得跟在动词后面</text></svg>","讲解":"的＋名词（定语），地＋动词（状语），得＋补语。口诀：的地得，不一样；名前的（白勺）的，动前的（土也）地，动后的得。","口诀":"白勺的贴名，土也地跟动，得后补结果","例子":["美丽的花","认真地听","跑得快","他高兴地笑了","这道题做得真好"],"易错":"的地得是小学高频错；记住\"的地得\"顺口溜","小测":[{"q":"\"认真_听讲\"填？","options":["的","地","得"],"answer":1,"解析":"修饰动词\"听\"，用\"地\"。"},{"q":"\"跑_很快\"填？","options":["的","地","得"],"answer":2,"解析":"动词后补结果，用\"得\"。"}]},{"name":"在/再","讲解":"“在”表处所、存在，“再”表重复、又一次。读音一样（zài），看意思选字。","例子":["我在教室里读书（处所）","妈妈说明天再去公园（又一次）","✗ 我在吃一次 → ✓ 我再吃一次"],"口诀":"处所在，再又来","易错":"✗ 请在说一遍 → ✓ 请再说一遍","类比":"“在”像图钉📌，钉住地点；“再”像回放键🔁，事情重来一遍。"},{"name":"做/作","讲解":"“做”多指具体动手干，“作”多指抽象创作。口语多用“做”，书面语“作”更多。","例子":["做作业、做饭、做游戏（动手）","作文、作品、作为（书面/抽象）","✗ 做文 → ✓ 作文"],"口诀":"动手做，动笔作","易错":"“作”是多音字（zuō/zuò），“作息”读 zuō"},{"name":"和/与","讲解":"“和”可做连词也可做介词，“与”是书面说法。做连词时前后能互换，做介词时不能。","例子":["我和妈妈去公园（连词，可换：妈妈和我）","我与妈妈（书面）","他和老师谈话（介词，不可换）"],"口诀":"能互换是连词","易错":"作介词时前后不能换，否则意思变了"},{"name":"把/被","讲解":"“把”字句强调处置（对宾语做了什么），“被”字句强调遭遇（主语受了什么）。","例子":["我把教室打扫干净了（我处置了教室）","小明被老师表扬了（小明受到表扬）","我喜欢音乐 → 不能改成“把”字句"],"口诀":"把字处置，被字受害","易错":"“被”后多为不如意事，说好事用“被”很别扭"},{"name":"吗/呢/吧","讲解":"“吗”问是非，“呢”问补充或反问，“吧”表商量、祈使。","例子":["你去吗？（是非问）","你呢？（补充问）","我们走吧！（商量）","快点吧！（催促）"],"口诀":"吗问是非，呢问补充，吧来商量","易错":"陈述句末不能加“吗”：✗ 我去吗学校"},{"name":"才/就","讲解":"“才”表晚、少、难（比想的晚/少），“就”表早、多、易（比想的早/多）。","例子":["他九点才起床（比想的晚）","他六点就起床了（比想的早）","这么难的题，他才用了五分钟（少）"],"口诀":"才嫌晚少难，就嫌早多易","易错":"时间+才/就，意思正好相反，别用反"},{"name":"都/也","讲解":"“都”表全部、总括，“也”表同样、类推。","例子":["同学们都来了（全部）","我也想去（同样）","他跑得快，我也跑得快"],"口诀":"都管全部，也管同样","易错":"✗ 全班都全部来了（“都”和“全部”重复）"},{"name":"以/已","讲解":"“以”表凭借、按照（yǐ），“已”表已经（yǐ）。同音不同义，看意思选。","例子":["他以第一名的成绩获奖（凭借）","我已经写完作业了（已经）","✗ 以经吃饭 → ✓ 已经吃饭"],"口诀":"以表凭借，已表已经","易错":"同音字，看偏旁区分"},{"name":"像/象","讲解":"“像”表相似、好像，“象”指大象或形状、现象。","例子":["他像爸爸一样高（相似）","大象的鼻子很长","✗ 气像 → ✓ 气象"],"口诀":"相似用单人像，大象气象用象","易错":"“好像”不能写成“好象”"},{"name":"必须/必需","讲解":"“必须”是副词，表一定要（后跟动词）；“必需”是动词，表一定需要（后跟名词）。","例子":["我们必须按时到校（后跟动词）","水是生命必需的（后跟名词）","✗ 必须品 → ✓ 必需品"],"口诀":"必须跟动作，必需跟东西","易错":"“必需品、日用品”用“必需”"},{"name":"哪/那","讲解":"“哪”表疑问（哪里、哪个），“那”表指示（那里、那个）。","例子":["你去哪里？（疑问）","我在那里等你（指示）","✗ 那里有几个人？→ ✓ 哪里有几个人？"],"口诀":"哪是问，那是指","易错":"问句用“哪”，回答用“那”"},{"name":"不/没","讲解":"“不”表主观不愿、经常性否定；“没”表客观没有、过去没发生。","例子":["我不去（不想去）","我没去（没去成）","他没来过北京（过去）","我不喜欢吃辣（经常）"],"口诀":"不表意愿，没表有无","易错":"“没”常和“过”搭配表过去：我没看过"},{"name":"还是/或者","讲解":"“还是”用于选择问句，“或者”用于陈述句表选择。","例子":["你喝水还是喝牛奶？（问句）","周末或者去公园，或者去图书馆（陈述）","✗ 你去或者不去？→ ✓ 你去还是不去？"],"口诀":"问句还是，陈述或者","易错":"问句里用“还是”，陈述句里用“或者”"}]}],"module":"语法知识库","标准":"《义务教育语文课程标准》附录三·语法修辞知识要点","说明":"覆盖词类、短语、单句成分、复句、修辞、病句六大块，为中考语文基础知识与作文语言服务"},"logic":{"categories":[{"id":"gainian","name":"形式逻辑基础","items":[{"name":"概念：定义与划分","类比":"概念就像抽屉标签：定义是写清标签上是什么，划分是把大抽屉分成小格。","讲解":"定义揭示内涵（是什么），划分揭示外延（有哪些）。定义=种差+属概念。","口诀":"定义讲内涵，划分列外延","例子":["白马不是马：白马（种）≠马（属），混淆层次","定义不能循环"],"易错":"划分标准要统一，不能一会儿按颜色一会儿按大小","动画":{"steps":[{"tokens":["属概念","＋","种差","＝","定义"],"note":"定义公式：先找大类（属），再说出区别（种差）"},{"tokens":["人","是","会制造工具的","动物"],"note":"动物（属）＋会制造工具（种差）＝人"},{"tokens":["✗","人","是","人类的一员"],"note":"错：循环定义，用\"人类\"解释\"人\"等于没说"}]},"小测":[{"q":"给\"学生\"下定义，哪个对？","options":["学生是上学的人","学生是在学校学习的人","学生是学生"],"answer":1,"解析":"属（人）＋种差（在学校学习）。A太宽，C循环。"}]},{"name":"三段论","类比":"三段论就像接力赛：大前提交棒给小前提，推出结论。","图示":"<svg viewBox=\"0 0 400 110\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"30\" y=\"30\" font-size=\"14\">大前提：知识分子都应受尊重</text><text x=\"30\" y=\"55\" font-size=\"14\">小前提：人民教师是知识分子</text><line x1=\"30\" y1=\"65\" x2=\"370\" y2=\"65\" stroke=\"#333\"/><text x=\"30\" y=\"90\" font-size=\"14\" font-weight=\"bold\">结论：人民教师应受尊重</text></svg>","讲解":"大前提（一般）+小前提（个别）→结论。","口诀":"大套小，推出结论跑不了","例子":["凡人皆有死，苏格拉底是人，所以苏格拉底有死"],"动画":{"steps":[{"tokens":["所有","人","都会","死"],"note":"大前提：一般道理"},{"tokens":["苏格拉底","是","人"],"note":"小前提：个别情况"},{"tokens":["所以","苏格拉底","会","死"],"note":"结论：水到渠成"}]},"小测":[{"q":"三段论哪项错了？大前提：鸟会飞。小前提：企鹅是鸟。结论：企鹅会飞","options":["大前提错了","小前提错了","推理错了"],"answer":0,"解析":"大前提\"鸟会飞\"不全真（鸵鸟企鹅不会），前提错结论就不可靠。"}]},{"name":"四大逻辑规律","类比":"四律就像思维交通规则：违反就撞车（自相矛盾）。","图示":"<svg viewBox=\"0 0 400 160\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"15\" y=\"10\" width=\"180\" height=\"65\" rx=\"8\" fill=\"#e8f5e9\"/><text x=\"25\" y=\"35\" font-size=\"14\" font-weight=\"bold\">同一律</text><text x=\"25\" y=\"58\" font-size=\"12\">咖啡不能一会儿变茶</text><rect x=\"205\" y=\"10\" width=\"180\" height=\"65\" rx=\"8\" fill=\"#ffebee\"/><text x=\"215\" y=\"35\" font-size=\"14\" font-weight=\"bold\">矛盾律</text><text x=\"215\" y=\"58\" font-size=\"12\">不能又下雨又没下雨</text><rect x=\"15\" y=\"85\" width=\"180\" height=\"65\" rx=\"8\" fill=\"#e3f2fd\"/><text x=\"25\" y=\"110\" font-size=\"14\" font-weight=\"bold\">排中律</text><text x=\"25\" y=\"133\" font-size=\"12\">灯只能开或关</text><rect x=\"205\" y=\"85\" width=\"180\" height=\"65\" rx=\"8\" fill=\"#fff3e0\"/><text x=\"215\" y=\"110\" font-size=\"14\" font-weight=\"bold\">充足理由律</text><text x=\"215\" y=\"133\" font-size=\"12\">说猫聪明要举例</text></svg>","讲解":"同一律（概念确定）、矛盾律（不自相矛盾）、排中律（非此即彼）、充足理由律（言之有据）。","口诀":"同一矛盾排中足，思维守法不糊涂","动画":{"steps":[{"tokens":["这杯","咖啡","不能","一会儿变茶"],"note":"同一律：概念要确定，前后一致"},{"tokens":["今天","下雨了","＋","没下雨","＝","✗"],"note":"矛盾律：不能自相矛盾"},{"tokens":["灯","开","或","关"],"note":"排中律：非此即彼，不许骑墙"},{"tokens":["猫聪明","因为","会开门"],"note":"充足理由律：说观点要给理由"}]}},{"name":"推理三兄弟：演绎/归纳/类比","类比":"演绎像\"漏斗\"（从大到小），归纳像\"堆塔\"（从小堆到大），类比如\"照镜子\"（看A像B）。","图示":"<svg viewBox=\"0 0 400 120\" xmlns=\"http://www.w3.org/2000/svg\"><polygon points=\"30,20 130,20 80,100\" fill=\"#e3f2fd\" stroke=\"#1976d2\"/><text x=\"45\" y=\"60\" font-size=\"12\">演绎↓</text><polygon points=\"160,100 260,100 210,20\" fill=\"#fff3e0\" stroke=\"#ef6c00\"/><text x=\"175\" y=\"60\" font-size=\"12\">归纳↑</text><rect x=\"290\" y=\"30\" width=\"80\" height=\"60\" rx=\"8\" fill=\"#f3e5f5\" stroke=\"#8e24aa\"/><text x=\"300\" y=\"65\" font-size=\"12\">类比⇄</text></svg>","讲解":"演绎：一般→个别（三段论）；归纳：个别→一般（看多了总结）；类比：A像B，B有某性→A也有。","口诀":"演绎漏斗归纳塔，类比照镜子","例子":["演绎：人会死→苏格拉底会死","归纳：乌鸦都是黑的（看了一万只）","类比：地球有水有生命→火星有水→可能有生命"],"易错":"归纳的\"枚举\"不完全会翻车（黑天鹅）；类比要本质像，不能表面像","小测":[{"q":"\"看到10只白天鹅，得出天鹅都是白的\"是什么推理？","options":["演绎","归纳","类比"],"answer":1,"解析":"从个别到一般，是归纳（不完全归纳，有风险）。"}]}]},{"id":"luojibing","name":"病句里的逻辑错误","items":[{"name":"自相矛盾","讲解":"前后说法打架：他是众多死难者中幸免的一个（都死了还幸免？）。","例子":["错：他是众多死难者中幸免的一个","对：他是众多遇难者中幸免的一个"],"易错":"检查前后分句能否同时为真","动画":{"steps":[{"tokens":["众多","死难者","中"],"note":"死难者＝已经死了"},{"tokens":["幸免","的","一个"],"note":"幸免＝没死"},{"tokens":["✗","死了","＋","没死"],"note":"撞车！改\"死难\"为\"遇难\""}]}},{"name":"主客倒置","讲解":"谁对谁说反了：京剧对她很熟悉→她对京剧很熟悉。","例子":["错：爱迪生这个名字对我们不陌生","对：我们对爱迪生这个名字不陌生"]},{"name":"强加因果","讲解":"无因果硬说因果：因为他来自北方，思想还是旧的一套。","易错":"问一句：前者真能推出后者吗"},{"name":"以偏概全","类比":"以偏概全就像\"盲人摸象\"：摸到腿说象是柱子，摸到鼻子说象是管子。","讲解":"拿部分当全部。看到几个就下结论全体，犯了\"简单枚举\"的错。","口诀":"部分推全体，十有八九错","例子":["错：我班三个同学近视，所以全班都近视","错：他北方人，北方人都豪爽"],"易错":"议论文举例后一定要\"扣题分析\"，不能例子一摆就下大结论"}]},{"id":"lunzheng","name":"议论文论证逻辑","items":[{"name":"举例论证","类比":"举例就像证人出庭：光有观点不行，得叫证人作证。","讲解":"公式：分论点+事例简述+扣题分析+小结回扣。事例是载体，分析才是灵魂。","口诀":"观点事例加分析，回扣分论才扎实","例子":["樊锦诗守敦煌：事例+坚守的分析+回扣"]},{"name":"道理论证","类比":"道理论证就像\"请权威背书\"：名人名言、定理公理往那一摆，分量立马不同。","讲解":"公式：分论点+名言/定理+阐释（为什么这句能证明观点）+回扣。","口诀":"名言开道，阐释跟上","例子":["论\"坚持\"：荀子\"锲而不舍，金石可镂\"+解释+回扣"],"易错":"名言不能堆砌，阐释（为什么适用）才是得分点"},{"name":"对比论证","类比":"对比就像\"照妖镜\"：正反一放，好坏立现。","讲解":"正面例子+反面例子+对比分析，得出结论。是非分明，说服力强。","口诀":"正反对照，是非自现","例子":["论\"勤奋\"：方仲永荒废 vs 匡衡凿壁"]},{"name":"常见谬误","类比":"谬误就像逻辑陷阱：看起来有道理，一脚踩空。","讲解":"偷换概念（白马非马式）、滑坡谬误（可能性变必然性）、人身攻击（不驳观点驳人）、稻草人（曲解对方再打）。","口诀":"偷滑人稻，谬误四套","例子":["滑坡：今天不上补习班，明天就考不上大学","人身攻击：他学习不好，他的话不可信"],"动画":{"steps":[{"tokens":["滑坡：","不上补习班","→","考不上大学"],"note":"可能性被说成必然性：每环因果经得起问吗？"},{"tokens":["人身攻击：","他成绩差","→","话不可信"],"note":"不驳观点驳人：成绩差≠观点错"},{"tokens":["稻草人：","曲解对方","→","打倒假想敌"],"note":"先歪曲再反驳：打的是自己立的靶子"}]},"小测":[{"q":"\"你这么胖，还好意思谈健康饮食？\"犯了什么谬误？","options":["滑坡谬误","人身攻击","偷换概念"],"answer":1,"解析":"攻击人而不反驳观点，是人身攻击。"}]}]},{"id":"tuili","name":"日常语言推理","items":[{"name":"言外之意","类比":"言外之意就像冰山：说出口的只是水面上的尖，意思藏在水下。","讲解":"合作原则：说话默认 truthful、相关、清楚。违反处即有言外之意。","例子":["问：蛋糕好吃吗？答：盘子很漂亮。（=不好吃）"]},{"name":"因果链","类比":"因果链就像多米诺：失了一颗铁钉，亡了一个帝国。","讲解":"找因果要一环扣一环，每环都经得起问为什么（5个为什么）。","例子":["铁钉→马掌→战马→将军→战争→帝国"]},{"name":"因果链：多米诺","类比":"因果就像多米诺骨牌：失了一颗铁钉，丢了一只马掌，亡了一个帝国。","图示":"<svg viewBox=\"0 0 400 90\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"30\" width=\"14\" height=\"40\" fill=\"#8e24aa\" transform=\"rotate(15 27 50)\"/><rect x=\"70\" y=\"30\" width=\"14\" height=\"40\" fill=\"#8e24aa\" transform=\"rotate(25 77 50)\"/><rect x=\"120\" y=\"35\" width=\"14\" height=\"40\" fill=\"#8e24aa\" transform=\"rotate(35 127 50)\"/><text x=\"180\" y=\"55\" font-size=\"14\">铁钉→马掌→战马→将军→帝国</text><text x=\"180\" y=\"75\" font-size=\"12\" fill=\"#888\">每环问一句\"为什么\"，5个为什么</text></svg>","动画":{"steps":[{"tokens":["少了","一颗铁钉"],"note":"起点：小得不起眼"},{"tokens":["丢了","一只马掌"],"note":"连锁：铁钉→马掌"},{"tokens":["亡了","一个帝国"],"note":"终点：蝴蝶效应"}]},"讲解":"找因果要一环扣一环，每环都问\"为什么\"，连续问5次到根因。","口诀":"因果链条环环扣，五个为什么问到底","小测":[{"q":"\"因为他是北方人，所以思想守旧\"错在哪环？","options":["籍贯推不出思想","北方人确实守旧","没错"],"answer":0,"解析":"籍贯→思想这环因果不成立，是强加因果。"}]}]}]},"reading":{"categories":[{"id":"tongyong","items":[{"name":"三遍阅读法","例子":["第一遍泛读：抓体裁、抓主旨","第二遍精读：析结构、圈关键句","第三遍跳读：带着题目找答案区"],"口诀":"泛读抓主旨，精读析结构，跳读找答案","易错":"切忌没读完文章就匆忙答题","讲解":"中考阅读的标准流程，先整体后局部"},{"name":"找中心句","例子":["开头总起句、结尾总结句","段落首句尾句"],"口诀":"开头结尾重点看，首尾常把中心担","易错":"中心句多是议论抒情句，不是叙事句","讲解":"中心句常出现在开头结尾、段落首尾，多为概括性语句"},{"name":"语境意识","例子":["词语含义到上下文中找","答案组织紧扣文章中心"],"口诀":"词不离句，句不离段，段不离篇","易错":"脱离文本的过度推断是丢分主因","讲解":"一切答案以文本为依据，联系上下文"},{"name":"关键句定位","例子":["体现作者立场的句子","过渡句、抒情议论句、比喻句"],"口诀":"立场过渡抒情议论，比喻连问要留神","易错":"独立成段的句子常有特殊作用","讲解":"开头句、结尾句、过渡句、抒情议论句常藏着主旨"}],"name":"通用阅读方法"},{"id":"tixing","items":[{"name":"概括内容","例子":["模式：什么人＋在什么情况下＋做什么事＋什么结果","如：本文记叙了小明在雨天坚持上学的故事"],"口诀":"人物事件加结果，要素齐全才算数","易错":"必须包括“人物+事情”两要素","讲解":"要素归纳法/合并段意法/摘录中心句"},{"name":"标题赏析","例子":["问：为什么以“灯”为题？","答：①本义（文章写灯）②深层（灯象征希望）③线索/主旨作用"],"口诀":"本义深层两层皮，线索主旨不能离","讲解":"标题是文眼：概括情节、作线索、点明中心、象征义"},{"name":"词句赏析","例子":["问：赏析“小草偷偷地钻出来”","答：①拟人手法②写出小草的生机与春天的气息③表达作者对春天的喜爱"],"口诀":"手法内容加主旨，三步走完是满分","易错":"只答手法不分析内容，或只谈内容不扣主旨","讲解":"万能三步：手法判定→内容解析→情感/主旨升华"},{"name":"结构作用","例子":["问：中间段落的作用？","答：承上启下；内容上深化主题/塑造形象"],"口诀":"结构内容两分说","易错":"开头段还可能是设置悬念、埋伏笔","讲解":"开头：开篇点题/设置悬念；中间：承上启下；结尾：总结/升华/首尾呼应"},{"name":"推断题","例子":["三步：定位依据→适度推理→验证选项"],"口诀":"回到原文找依据，适度推理不臆断","易错":"排除“原文直接出现”（不是推断）、“过度推断”、“逻辑矛盾”项","讲解":"基于原文信息的适度推理，不夸大不缩小"},{"name":"开放探究","例子":["问：你认同作者的观点吗？为什么？","答：观点明确（我认为……）+文本支撑（引用原文）+联系实际"],"口诀":"观点明确，文本支撑，联系实际","易错":"只表态不给理由，或理由脱离文本","讲解":"立场+论据（原文）+引申，言之成理即可"}],"name":"常考题型与答题公式"},{"id":"wenti","items":[{"name":"记叙文","例子":["六要素：时间地点人物，起因经过结果","线索：人物/事件/情感/物品"],"口诀":"六要素加线索，记叙文不迷路","易错":"","讲解":"以叙事写人为核心，抓线索理思路"},{"name":"议论文","例子":["论点（中心论点/分论点）","论据（事实/道理）","论证（举例/道理/对比/比喻）"],"口诀":"论点论据论证，三要素要分清","易错":"中心论点常在标题或开头结尾","讲解":"观点+材料+证明方法"},{"name":"说明文","例子":["说明对象+说明方法（举例子/列数字/打比方/作比较）","说明顺序：时间/空间/逻辑"],"口诀":"对象方法加顺序","易错":"说明方法判断是高频考点","讲解":"介绍事物事理，语言准确平实"},{"name":"散文","例子":["形散神聚：线索串材料","借景抒情、托物言志"],"口诀":"线索串珠，情感是魂","易错":"散文主旨常含蓄，要读出言外之意","讲解":"抒情性强，意境优美"}],"name":"文体辨识与策略"}],"module":"阅读理解方法技巧库","标准":"综合中考语文阅读题型与课标阅读要求整理","说明":"覆盖通用阅读方法、六大常考题型答题公式、四大文体策略，与语法库的修辞/句式知识联动"},"writing":{"categories":[{"id":"shenti","items":[{"name":"抓题眼","例子":["《那盏灯》：“灯”是题眼，引申为希望/指引","《温暖》：“温暖”是情感核心"],"口诀":"瞻前顾后一字不漏，题眼就是开门钥匙","易错":"跑题多因没审清题眼","讲解":"精细审题第一步：圈关键词，找准题目核心词（题眼）"},{"name":"辨题型","例子":["命题作文：按题目写；材料作文：抓关键句立意","半命题：先补题再写"],"口诀":"文题类型先分清，含义文体都要明","易错":"材料作文最忌断章取义、只抓局部","讲解":"注意文题类型、含义、文体类别、选材指向、立意信息"},{"name":"审题六审","例子":["一审文题类型，二审文题含义，三审题眼，四审文体，五审选材指向，六审立意信息"],"口诀":"类型含义题眼，文体选材立意","易错":"","讲解":"中考作文复习指导总结的审题六个要点"}],"name":"审题"},{"id":"liyi","items":[{"name":"立意三标准","例子":["正确（价值观端正）","集中（一个中心）","深刻（有思考）"],"口诀":"中心是灵魂，正确集中深","易错":"立意贪多求全是大忌","讲解":"确立文章中心思想，犹如文章灵魂"},{"name":"立意八类","例子":["生命意义：生活感悟的滋味","自然景物：对周遭世界的感悟","情感体验：珍藏的人和事","享受幸福：温暖与智慧的情节","成功成长：花季酸甜苦辣","道德修养：诚信/勇敢/善良","哲理品悟：生活细节提炼规律","告别往昔：值得珍藏的片段"],"口诀":"生命自然情感，幸福成长道德，哲理告别","易错":"8类有交叉，按题目选最贴切的一类","讲解":"中高考作文立意范畴基本不出这8类，备考时每类准备一个典型题材"},{"name":"审题立意方法（材料作文）","例子":["抓关键句法、主旨倾向法、由果溯因法、求同分析法、辩证分析法"],"口诀":"全面分析抓关键，辩证因果多角度","易错":"过多纠缠局部细节会偏题","讲解":"高考常用：先整体把握材料，再抓关键词句作突破口，用辩证/因果/对比等思维多角度审视"}],"name":"立意"},{"id":"xuancai","items":[{"name":"选材三原则","例子":["熟悉（亲身经历）","动情（真体验真感受）","独特（与众不同）"],"口诀":"熟悉动情加独特，第一人称最稳妥","易错":"考场瞎编乱造易出纰漏","讲解":"选自己最熟悉、最动情的生活来写，用第一人称写亲身经历"},{"name":"素材积累","例子":["8个立意范畴各备1个典型题材","平时记录：春花秋月、校园草木、家庭琐事"],"口诀":"8类题材常备，观察生活常记","易错":"","讲解":"把8个立意范畴各准备一个生动题材，考场直接调用"},{"name":"细节描写","例子":["写人：外貌/动作/神态/语言/心理","写事：细节+环境描写","抓住“最动人的那个细节”"],"口诀":"人物六描写，事件抓细节","易错":"没有细节的叙事是流水账","讲解":"细节是记叙文的生命，环境描写烘托气氛"}],"name":"选材"},{"id":"jiegou","items":[{"name":"总分总结构","例子":["开头点题→中间分述→结尾升华","记叙文可用1-3-1或1-4-1（开头1段、中间3-4段、结尾1段）"],"口诀":"总分总最稳，六七段最顺","易错":"忌“大肚子作文”（中间一段超长）/大头/大尾巴","讲解":"考场最保险的结构；六七百字配六七段，视觉协调"},{"name":"一线穿珠","例子":["以人物品质为主线，串起几个典型片段","如《我的老师》"],"口诀":"一线串珠不旁逸","易错":"","讲解":"无贯穿中心事件时，以人物活动/品质为主线组织材料"},{"name":"开头技巧","例子":["一句话开头：直接交代时间地点人物事件","悬念开头/名句开头/排比开头"],"口诀":"开头不过5行，开门见山最行","易错":"开头玩技巧过长会喧宾夺主","讲解":"开篇两三句点出记叙要点或明确主题，简洁洗练"},{"name":"结尾技巧","例子":["抒情结尾：升华情感","议论结尾：点明哲理、照应标题"],"口诀":"结尾抒情或议论，照应标题点中心","易错":"结尾忌另起新话题","讲解":"记叙文结尾抒情+哲理，议论文结尾重申论点"}],"name":"结构"},{"id":"yuyan","items":[{"name":"短句为主","例子":["一个句子主谓宾定状补齐了，就用句号","忌一逗到底"],"口诀":"短句有力，长句易病","易错":"长句最易犯语病（呼应语法库病句）","讲解":"句子短促有力，节奏好且不易出错"},{"name":"修辞点缀","例子":["比喻拟人排比设问，点缀2-3处即可"],"口诀":"修辞2-3处，语言即出彩","易错":"堆砌修辞会油腻","讲解":"呼应语法库8种修辞，恰当使用让语言出彩"},{"name":"描写升级","例子":["动作描写：连续动词","语言描写：神态+潜台词","环境描写：烘托人物心情"],"口诀":"写人要有动作语言，写事要有细节环境","易错":"","讲解":"描写是把“讲故事”变成“演故事”的关键"}],"name":"语言"}],"module":"写作技巧库","标准":"综合中高考作文指导（审题/立意/选材/结构/语言）与课标写作要求整理","说明":"覆盖考场作文全流程：审题→立意→选材→结构→语言，与语法库（病句/修辞/句式）联动"}};